/* BANK SOAL BAGIAN B — Persiapan Tes Bank Sumsel Babel (Analis Kredit)
   Kontrak: const SOAL_B = [{id, modul, kategori, level:1|2|3, soal,
             opsi:[5 string tanpa huruf A-E], kunci:0-4, pembahasan}]
   modul: analisis-kredit | slik-rasio-hitungan | studi-kasus */
const SOAL_B = [
{id:"AK-001", modul:"analisis-kredit", kategori:"Prinsip 5C", level:1, soal:"Pasal 8 ayat (1) UU No. 10 Tahun 1998 mewajibkan bank memiliki keyakinan atas itikad dan kemampuan debitur berdasarkan analisis yang mendalam. Dalam praktik perbankan, keyakinan tersebut dibangun melalui penilaian atas", opsi:["watak, kemampuan, modal, agunan, dan prospek usaha calon debitur (prinsip 5C)","besarnya nilai agunan yang diserahkan debitur saja","laporan keuangan satu tahun terakhir tanpa verifikasi","rekomendasi pejabat bank tanpa analisis tertulis","jumlah dana pihak ketiga yang dimiliki debitur"], kunci:0, pembahasan:"Kunci benar karena prinsip 5C (Character, Capacity, Capital, Collateral, Condition) adalah kerangka praktik umum untuk memenuhi amanat Pasal 8 ayat (1) UU 10/1998. Pengecoh salah karena agunan saja, laporan keuangan tanpa verifikasi, rekomendasi tanpa analisis, dan jumlah simpanan tidak mencerminkan itikad maupun kemampuan bayar debitur secara utuh."},
{id:"AK-002", modul:"analisis-kredit", kategori:"Prinsip 5C", level:1, soal:"Dalam prinsip 5C, Character menilai", opsi:["kemampuan teknis mengelola usaha","kemauan dan itikad baik calon debitur untuk memenuhi kewajibannya (willingness to pay)","besarnya modal yang ditanam pemilik","nilai likuidasi agunan yang diserahkan","kondisi makroekonomi yang memengaruhi usaha"], kunci:1, pembahasan:"Kunci benar karena Character mengukur kemauan membayar, dinilai dari riwayat pembayaran, reputasi, dan hasil wawancara. Kemampuan teknis adalah Capacity, modal sendiri adalah Capital, nilai agunan adalah Collateral, dan kondisi makro adalah Condition."},
{id:"AK-003", modul:"analisis-kredit", kategori:"Prinsip 5C", level:1, soal:"Dalam prinsip 5C, Capacity menilai", opsi:["kejujuran calon debitur","nilai pasar agunan","kemampuan calon debitur menghasilkan arus kas untuk membayar kewajibannya (ability to pay)","jumlah modal disetor pemilik","prospek industri lima tahun ke depan"], kunci:2, pembahasan:"Kunci benar karena Capacity mengukur kemampuan membayar yang bersumber dari arus kas usaha. Kejujuran adalah Character, nilai agunan adalah Collateral, modal disetor adalah Capital, dan prospek industri adalah Condition."},
{id:"AK-004", modul:"analisis-kredit", kategori:"Prinsip 5C", level:1, soal:"Dalam prinsip 5C, Capital menilai", opsi:["kemauan membayar debitur","arus kas operasional usaha","nilai taksiran agunan","besarnya modal sendiri yang ditanam pemilik ke dalam usaha","tren suku bunga pasar"], kunci:3, pembahasan:"Kunci benar karena Capital melihat seberapa besar dana sendiri yang dipertaruhkan pemilik, yang mencerminkan keseriusan dan daya tahan modal. Kemauan membayar adalah Character, arus kas adalah Capacity, nilai agunan adalah Collateral, dan tren suku bunga adalah Condition."},
{id:"AK-005", modul:"analisis-kredit", kategori:"Prinsip 5C", level:1, soal:"Dalam prinsip 5C, Collateral berfungsi sebagai", opsi:["sumber pelunasan utama kredit","pengganti analisis arus kas","penentu besarnya suku bunga","jaminan tambahan sebagai pengaman apabila debitur gagal bayar","syarat mutlak yang besarnya harus melebihi plafon"], kunci:4, pembahasan:"Kunci benar karena agunan adalah pengaman kedua (secondary source of repayment), sedangkan pelunasan utama tetap dari arus kas usaha. Pengecoh salah karena agunan tidak menggantikan analisis arus kas, tidak menentukan bunga, dan tidak wajib melebihi plafon selama coverage memadai sesuai kebijakan bank."},
{id:"AK-006", modul:"analisis-kredit", kategori:"Prinsip 5C", level:2, soal:"Harga komoditas sawit anjlok 40 persen dalam setahun. Bagi calon debitur perkebunan kelapa sawit, faktor 5C yang paling terdampak oleh peristiwa tersebut adalah", opsi:["Condition, karena kondisi ekonomi dan industri memengaruhi kemampuan usaha debitur","Character, karena harga jatuh mencerminkan itikad debitur","Capital, karena harga komoditas menambah modal sendiri","Collateral, karena harga sawit menaikkan nilai agunan","Capacity, karena anjloknya harga otomatis menambah arus kas"], kunci:0, pembahasan:"Kunci benar karena Condition menilai pengaruh kondisi ekonomi, industri, dan pasar terhadap usaha debitur. Harga komoditas bukan ukuran itikad (Character), tidak menambah modal (Capital), tidak otomatis menaikkan agunan (Collateral), dan justru menekan arus kas sehingga melemahkan Capacity, bukan menambahnya."},
{id:"AK-007", modul:"analisis-kredit", kategori:"Prinsip 5C", level:2, soal:"Cara yang paling tepat untuk menilai Character calon debitur adalah", opsi:["menilai besarnya omzet usaha","menghitung rasio keuangan","menilai harga pasar agunan","memeriksa riwayat pembayaran pada SLIK, reputasi usaha, dan hasil wawancara","membandingkan suku bunga antarbank"], kunci:1, pembahasan:"Kunci benar karena Character dinilai dari rekam jejak pembayaran (SLIK/iDeb), reputasi di lingkungan usaha, dan konsistensi informasi saat wawancara. Omzet, rasio keuangan, dan nilai agunan mengukur Capacity/Collateral, sedangkan suku bunga antarbank tidak relevan dengan watak debitur."},
{id:"AK-008", modul:"analisis-kredit", kategori:"Prinsip 5C", level:2, soal:"Untuk menilai Capacity secara paling meyakinkan, analis kredit sebaiknya berfokus pada", opsi:["besarnya laba akuntansi tahun berjalan","nilai buku aset tetap perusahaan","proyeksi arus kas usaha dan rasio kemampuan membayar seperti DSCR","jumlah karyawan perusahaan","lamanya perusahaan berdiri"], kunci:2, pembahasan:"Kunci benar karena Capacity adalah kemampuan membayar yang hanya terbukti dari arus kas, bukan dari laba akuntansi yang bisa dipengaruhi kebijakan akuntansi. Nilai buku aset, jumlah karyawan, dan umur perusahaan tidak menunjukkan kemampuan membayar cicilan."},
{id:"AK-009", modul:"analisis-kredit", kategori:"Prinsip 5C", level:3, soal:"Struktur permodalan calon debitur menunjukkan ekuitas hanya 10 persen dari total aset. Implikasi penilaian Capital yang tepat adalah", opsi:["struktur modal sehat karena utang kecil","pemilik menanggung risiko besar sehingga kredit aman","leverage sangat tinggi sehingga daya tahan modal lemah dan risiko kredit meningkat","modal tipis tidak masalah selama omzet besar","bank wajib menolak karena ekuitas di bawah 50 persen"], kunci:3, pembahasan:"Kunci benar karena ekuitas 10 persen berarti 90 persen aset dibiayai utang (DER 9x), sehingga bantalan modal sangat tipis terhadap kerugian. Pengecoh salah karena utang justru besar, pemilik menanggung risiko kecil, omzet besar tidak menutup struktur modal rapuh, dan tidak ada aturan baku penolakan pada angka 50 persen."},
{id:"AK-010", modul:"analisis-kredit", kategori:"Prinsip 5C", level:2, soal:"Penilaian Collateral yang baik mencakup", opsi:["nilai perolehan agunan menurut debitur","nilai likuidasi, kemudahan eksekusi, dan kelengkapan legalitas dokumen kepemilikan","harga penawaran di brosur pemasaran","nilai agunan menurut taksiran lisan","luas agunan tanpa memperhatikan status sertifikat"], kunci:4, pembahasan:"Kunci benar karena bank hanya dapat mengandalkan agunan bila nilainya realistis saat dijual paksa, mudah dieksekusi, dan dokumennya sah. Nilai menurut debitur, brosur, taksiran lisan, dan luas tanpa status sertifikat tidak memberi kepastian hukum maupun nilai bagi bank."},
{id:"AK-011", modul:"analisis-kredit", kategori:"Prinsip 5C", level:3, soal:"Dua calon debitur memiliki Character, Capacity, Capital, dan Collateral yang setara, tetapi yang satu bergerak di industri batubara yang sedang lesu dan satunya di industri makanan pokok yang stabil. Perbedaan keputusan kredit di antara keduanya terutama bersumber dari penilaian", opsi:["Condition, yaitu prospek dan kondisi industri yang memengaruhi kelangsungan usaha","Character, karena industri lesu mencerminkan watak buruk","Capital, karena industri makanan otomatis bermodal besar","Collateral, karena agunan tambang selalu lebih rendah","Capacity, karena industri stabil pasti berarus kas besar"], kunci:0, pembahasan:"Kunci benar karena Condition menilai faktor eksternal seperti siklus industri yang berada di luar kendali debitur. Pengecoh salah karena kondisi industri bukan ukuran watak, tidak otomatis menentukan modal atau nilai agunan, dan industri stabil pun tetap harus diuji arus kasnya satu per satu."},
{id:"AK-012", modul:"analisis-kredit", kategori:"Prinsip 5C", level:3, soal:"Calon debitur memiliki Character dan Capacity yang kuat, tetapi nilai agunan hanya menutupi 60 persen dari plafon yang diminta. Keputusan analisis yang tepat menurut prinsip 5C adalah", opsi:["menolak karena agunan wajib menutupi 100 persen plafon","kredit tetap dapat dipertimbangkan karena agunan hanya pengaman kedua, dengan mitigasi seperti penurunan plafon, asuransi, atau agunan tambahan","menaikkan suku bunga agar menutupi kekurangan agunan","meminta debitur menambah utang agar coverage naik","menyetujui penuh karena Character baik menghapus kebutuhan agunan"], kunci:1, pembahasan:"Kunci benar karena sumber pelunasan utama adalah arus kas (Capacity), sedangkan agunan berfungsi sebagai pengaman. Kekurangan coverage diatasi dengan mitigasi, bukan ditutup dengan menaikkan bunga atau menambah utang. Character yang baik pun tidak menghapus kebutuhan pengaman sesuai kebijakan bank."},
{id:"AK-013", modul:"analisis-kredit", kategori:"Prinsip 5C", level:3, soal:"Pada masa kontraksi ekonomi yang tajam, dari lima faktor 5C, faktor yang bobot pengujiannya paling meningkat bagi analis kredit adalah", opsi:["Character, karena resesi menguji kejujuran","Capital, karena modal bertambah saat resesi","Condition, karena daya tahan usaha terhadap guncangan ekonomi menjadi penentu kelangsungan","Collateral, karena nilai agunan naik saat resesi","Capacity historis, karena masa lalu selalu berulang"], kunci:2, pembahasan:"Kunci benar karena Condition menguji sensitivitas usaha terhadap siklus ekonomi, yang menjadi faktor pembeda saat resesi. Resesi tidak menambah modal, umumnya menekan nilai agunan, dan kinerja masa lalu belum tentu berulang sehingga proyeksi harus diuji ulang."},
{id:"AK-014", modul:"analisis-kredit", kategori:"Prinsip 5C", level:3, soal:"Dalam alur analisis 5C yang lazim, penilaian Character umumnya didahulukan karena", opsi:["Character paling mudah dihitung dengan rumus","debitur yang beritikad buruk akan berisiko apa pun bagusnya angka keuangan, sehingga screening awal menghemat sumber daya analisis","regulator mewajibkan urutan baku 5C","Character menentukan besarnya plafon","agunan hanya bisa dinilai setelah Character"], kunci:3, pembahasan:"Kunci benar karena kemauan membayar adalah prasyarat; debitur yang tidak beritikad baik membuat analisis keuangan menjadi sia-sia. Tidak ada rumus baku maupun urutan yang diwajibkan regulator untuk 5C, Character tidak menentukan plafon, dan penilaian agunan tidak bergantung pada urutan Character."},
{id:"AK-015", modul:"analisis-kredit", kategori:"Prinsip 7P", level:1, soal:"Dalam prinsip 7P, Personality menilai", opsi:["tujuan penggunaan dana kredit","prospek usaha yang dibiayai","kemampuan menghasilkan laba","perlindungan berupa agunan dan asuransi","kepribadian, itikad, dan integritas calon debitur"], kunci:4, pembahasan:"Kunci benar karena Personality sejajar dengan Character pada 5C, yaitu menilai watak dan integritas. Tujuan penggunaan adalah Purpose, prospek usaha adalah Prospect, kemampuan laba adalah Profitability, dan perlindungan adalah Protection."},
{id:"AK-016", modul:"analisis-kredit", kategori:"Prinsip 7P", level:1, soal:"Dalam prinsip 7P, Party berarti", opsi:["penggolongan atau klasifikasi pihak debitur, misalnya perorangan, badan usaha, atau kelompok usaha","pesta perayaan pencairan kredit","pihak bank sebagai kreditur","pembagian keuntungan bank","pihak asuransi penjamin"], kunci:0, pembahasan:"Kunci benar karena Party mengklasifikasikan golongan debitur agar analisis disesuaikan dengan karakteristik masing-masing pihak. Pengecoh lain tidak berkaitan dengan konsep Party dalam analisis kredit."},
{id:"AK-017", modul:"analisis-kredit", kategori:"Prinsip 7P", level:1, soal:"Dalam prinsip 7P, Purpose menilai", opsi:["besarnya laba perusahaan","tujuan penggunaan dana kredit, misalnya modal kerja, investasi, atau konsumsi","jangka waktu kredit","suku bunga yang dikenakan","nilai agunan"], kunci:1, pembahasan:"Kunci benar karena Purpose memastikan dana dipakai sesuai peruntukannya sehingga sumber pelunasannya jelas. Laba adalah Profitability, jangka waktu dan bunga adalah syarat kredit, dan agunan adalah Protection."},
{id:"AK-018", modul:"analisis-kredit", kategori:"Prinsip 7P", level:2, soal:"Calon debitur mengajukan kredit untuk ekspansi ke lini produk baru. Penilaian 7P yang paling menguji kelayakan rencana ekspansi tersebut adalah", opsi:["Personality, karena ekspansi menguji kepribadian","Payment, karena ekspansi pasti mempercepat pelunasan","Prospect, yaitu prospek usaha dan daya tahan rencana bisnis ke depan","Party, karena produk baru mengubah golongan debitur","Protection, karena ekspansi menambah agunan otomatis"], kunci:2, pembahasan:"Kunci benar karena Prospect menilai prospek usaha yang dibiayai, termasuk kewajaran rencana ekspansi. Kepribadian tidak menguji kelayakan bisnis, ekspansi tidak otomatis mempercepat pelunasan, golongan debitur tidak berubah karena produk baru, dan ekspansi tidak otomatis menambah agunan."},
{id:"AK-019", modul:"analisis-kredit", kategori:"Prinsip 7P", level:2, soal:"Dalam prinsip 7P, Payment menekankan pada", opsi:["cara bank membayar gaji analis","sumber dan kemampuan pelunasan kembali kredit oleh debitur","pembayaran premi asuransi","pembayaran pajak bank","jadwal pencairan bertahap"], kunci:3, pembahasan:"Kunci benar karena Payment menilai dari mana dan bagaimana kredit akan dilunasi, misalnya dari arus kas usaha. Pengecoh lain berkaitan dengan operasional bank, bukan pelunasan kredit debitur."},
{id:"AK-020", modul:"analisis-kredit", kategori:"Prinsip 7P", level:2, soal:"Dalam prinsip 7P, Profitability menilai", opsi:["laba bank dari penyaluran kredit","kemampuan usaha debitur menghasilkan laba secara berkelanjutan","besarnya dividen yang dibagikan","keuntungan penjualan agunan","margin bunga bank"], kunci:4, pembahasan:"Kunci benar karena Profitability melihat kemampuan usaha menghasilkan laba sebagai fondasi kemampuan bayar jangka panjang. Laba bank, dividen, keuntungan penjualan agunan, dan margin bunga bank bukan objek penilaian Profitability debitur."},
{id:"AK-021", modul:"analisis-kredit", kategori:"Prinsip 7P", level:3, soal:"Dalam prinsip 7P, Protection mencakup agunan, asuransi, dan pengikatan yang kuat. Fungsi utama Protection dalam keputusan kredit adalah", opsi:["menjadi sumber pelunasan utama menggantikan arus kas","memberi lapisan pengaman dan kepastian hukum bila sumber pelunasan utama terganggu","menaikkan plafon tanpa batas","menghapus kewajiban analisis lainnya","menjamin kredit pasti disetujui"], kunci:0, pembahasan:"Kunci benar karena Protection adalah pengaman kedua; pelunasan utama tetap dari kemampuan bayar debitur. Pengecoh salah karena Protection tidak menggantikan arus kas, tidak menaikkan plafon tanpa batas, tidak menghapus analisis lain, dan tidak menjamin persetujuan."},
{id:"AK-022", modul:"analisis-kredit", kategori:"Prinsip 7P", level:3, soal:"Perbedaan utama kerangka 7P dibandingkan 5C terletak pada penambahan penilaian", opsi:["Character dan Capacity","Collateral dan Condition","Purpose, Prospect, dan Party, yaitu tujuan kredit, prospek usaha, dan klasifikasi pihak debitur","Capital dan Collateral","Payment dan Profitability saja"], kunci:1, pembahasan:"Kunci benar karena 7P menambahkan Purpose (tujuan), Prospect (prospek), dan Party (golongan pihak) di samping unsur yang sepadan dengan 5C. Character, Capacity, Capital, Collateral, dan Condition sudah tercakup dalam 5C, sedangkan Payment dan Profitability adalah pendalaman dari Capacity."},
{id:"AK-023", modul:"analisis-kredit", kategori:"Penyelamatan 3R", level:1, soal:"Rescheduling dalam penyelamatan kredit berarti", opsi:["penghapusan seluruh utang debitur","penambahan plafon kredit baru","penjadwalan ulang pembayaran, misalnya perpanjangan jangka waktu kredit","penurunan suku bunga kredit","pengalihan kredit ke bank lain"], kunci:2, pembahasan:"Kunci benar karena rescheduling mengubah jadwal atau tenor pembayaran kembali. Penghapusan utang bukan 3R, penambahan plafon adalah restructuring, penurunan bunga adalah reconditioning, dan pengalihan ke bank lain bukan penyelamatan oleh bank."},
{id:"AK-024", modul:"analisis-kredit", kategori:"Penyelamatan 3R", level:1, soal:"Reconditioning dalam penyelamatan kredit berarti", opsi:["penjadwalan ulang tenor","penambahan fasilitas kredit","penghapusbukuan kredit macet","persyaratan ulang atas sebagian atau seluruh syarat kredit, misalnya perubahan suku bunga atau penundaan pembayaran bunga","penjualan agunan"], kunci:3, pembahasan:"Kunci benar karena reconditioning mengubah persyaratan kredit seperti tingkat bunga dan perlakuan atas tunggakan bunga. Penjadwalan ulang adalah rescheduling, penambahan fasilitas adalah restructuring, sedangkan hapus buku dan jual agunan adalah penyelesaian kredit bermasalah, bukan 3R."},
{id:"AK-025", modul:"analisis-kredit", kategori:"Penyelamatan 3R", level:1, soal:"Restructuring dalam penyelamatan kredit berarti", opsi:["perpanjangan tenor saja","penurunan suku bunga saja","penagihan intensif","penataan ulang syarat-syarat kredit yang dapat mencakup penambahan fasilitas pembiayaan","penghapusan denda keterlambatan saja"], kunci:4, pembahasan:"Kunci benar karena restructuring adalah penataan ulang menyeluruh termasuk kemungkinan tambahan pembiayaan agar usaha kembali berjalan. Perpanjangan tenor saja adalah rescheduling, penurunan bunga saja adalah reconditioning, sedangkan penagihan dan penghapusan denda bukan 3R."},
{id:"AK-026", modul:"analisis-kredit", kategori:"Penyelamatan 3R", level:2, soal:"Bank menyepakati penurunan suku bunga kredit dari 12 persen menjadi 9 persen serta penundaan pembayaran bunga selama 6 bulan bagi debitur yang kesulitan. Langkah ini termasuk", opsi:["reconditioning, karena mengubah persyaratan kredit berupa tingkat bunga dan perlakuan bunga","rescheduling, karena hanya mengubah jadwal","restructuring, karena menambah fasilitas","hapus tagih","novasi"], kunci:0, pembahasan:"Kunci benar karena perubahan suku bunga dan penundaan bunga adalah perubahan persyaratan (reconditioning). Bukan rescheduling karena tenor tidak diubah, bukan restructuring karena tidak ada tambahan fasilitas, dan bukan hapus tagih maupun novasi."},
{id:"AK-027", modul:"analisis-kredit", kategori:"Penyelamatan 3R", level:2, soal:"Jangka waktu kredit debitur diperpanjang dari 3 tahun menjadi 5 tahun agar cicilan bulanan turun dan terjangkau arus kas. Langkah ini termasuk", opsi:["reconditioning","rescheduling, karena mengubah jadwal dan jangka waktu pembayaran kembali","restructuring","refinancing","take over"], kunci:1, pembahasan:"Kunci benar karena perpanjangan tenor adalah penjadwalan ulang pembayaran. Bukan reconditioning karena suku bunga dan syarat lain tidak diubah, bukan restructuring karena tidak ada penataan menyeluruh plus tambahan fasilitas."},
{id:"AK-028", modul:"analisis-kredit", kategori:"Penyelamatan 3R", level:3, soal:"Debitur membutuhkan perpanjangan tenor sekaligus tambahan modal kerja agar usahanya pulih. Kombinasi langkah penyelamatan yang tepat adalah", opsi:["rescheduling saja","reconditioning saja","restructuring, karena mencakup penataan ulang syarat kredit termasuk penambahan fasilitas pembiayaan","hapus buku","penjualan agunan segera"], kunci:2, pembahasan:"Kunci benar karena kebutuhan ganda (tenor plus tambahan dana) hanya terwadahi restructuring yang memungkinkan penambahan fasilitas. Rescheduling atau reconditioning saja tidak memberi tambahan modal, sedangkan hapus buku dan jual agunan adalah langkah penyelesaian, bukan penyelamatan usaha yang masih prospektif."},
{id:"AK-029", modul:"analisis-kredit", kategori:"Tahapan Kredit", level:1, soal:"Urutan tahapan pemberian kredit yang lazim dalam praktik perbankan adalah", opsi:["pencairan, analisis, permohonan, keputusan, dokumentasi, monitoring","permohonan, keputusan, analisis, pencairan, dokumentasi, monitoring","analisis, permohonan, dokumentasi, keputusan, monitoring, pencairan","permohonan, analisis, keputusan, dokumentasi dan pengikatan, pencairan, monitoring","monitoring, permohonan, analisis, keputusan, pencairan, dokumentasi"], kunci:3, pembahasan:"Kunci benar karena alur logisnya adalah permohonan, analisis, keputusan, dokumentasi/pengikatan, pencairan, lalu monitoring. Pengecoh salah karena menempatkan pencairan sebelum analisis dan pengikatan, atau monitoring di awal proses."},
{id:"AK-030", modul:"analisis-kredit", kategori:"Tahapan Kredit", level:1, soal:"Surat penawaran pemberian kredit (SPPK) diterbitkan bank pada tahap", opsi:["permohonan","analisis","dokumentasi","pencairan","keputusan atau persetujuan kredit"], kunci:4, pembahasan:"Kunci benar karena SPPK adalah pemberitahuan resmi persetujuan setelah komite kredit memutuskan. Pada tahap permohonan bank baru menerima berkas, tahap analisis masih mengkaji, dokumentasi menyiapkan pengikatan, dan pencairan adalah realisasi dana."},
{id:"AK-031", modul:"analisis-kredit", kategori:"Tahapan Kredit", level:2, soal:"Pengikatan agunan secara notaril dan pembebanan hak tanggungan atau fidusia dilakukan pada tahap", opsi:["dokumentasi, dan harus selesai sebelum pencairan","permohonan","monitoring","penagihan","setelah kredit lunas"], kunci:0, pembahasan:"Kunci benar karena pengikatan adalah bagian dokumentasi yang wajib tuntas sebelum dana dicairkan agar bank memiliki kedudukan hukum atas agunan. Tahap permohonan baru pengumpulan dokumen, monitoring dan penagihan terjadi setelah pencairan."},
{id:"AK-032", modul:"analisis-kredit", kategori:"Tahapan Kredit", level:2, soal:"Tujuan utama monitoring dan pembinaan debitur setelah pencairan adalah", opsi:["menambah plafon secara otomatis","mendeteksi dini penurunan kualitas kredit dan membina usaha debitur agar tetap lancar","menagih denda keterlambatan","mengganti analis kredit","menutup rekening debitur"], kunci:1, pembahasan:"Kunci benar karena monitoring bersifat preventif dan pembinaan menjaga kelangsungan usaha sumber pelunasan. Penambahan plafon tidak otomatis, penagihan denda bersifat kuratif, dan penggantian analis maupun penutupan rekening bukan tujuan monitoring."},
{id:"AK-033", modul:"analisis-kredit", kategori:"Tahapan Kredit", level:3, soal:"Kredit dicairkan padahal pengikatan hak tanggungan belum selesai karena desakan target bisnis. Risiko utama yang dihadapi bank adalah", opsi:["risiko suku bunga","risiko hukum karena bank belum memiliki hak preferensi atas agunan sehingga kedudukannya lemah bila debitur gagal bayar","risiko nilai tukar","risiko operasional pada sistem IT","tidak ada risiko selama debitur membayar lancar"], kunci:2, pembahasan:"Kunci benar karena tanpa pengikatan yang sempurna bank tidak memegang hak eksekusi yang didahulukan atas agunan. Risiko suku bunga, nilai tukar, dan IT tidak relevan, dan kelancaran pembayaran saat ini tidak menghapus cacat yuridis tersebut."},
{id:"AK-034", modul:"analisis-kredit", kategori:"Arus Kas & Kapasitas Bayar", level:1, soal:"Sumber pelunasan utama kredit yang paling diandalkan analis adalah", opsi:["penjualan agunan","dana talangan dari pemilik","utang baru dari bank lain","arus kas dari kegiatan usaha debitur","pencairan asuransi"], kunci:3, pembahasan:"Kunci benar karena kredit yang sehat dilunasi dari arus kas usaha (primary source of repayment). Penjualan agunan, talangan pemilik, utang baru, dan asuransi hanyalah sumber cadangan atau pengaman, bukan sumber utama."},
{id:"AK-035", modul:"analisis-kredit", kategori:"Arus Kas & Kapasitas Bayar", level:2, soal:"Untuk kredit modal kerja perdagangan, sumber pelunasan yang paling sesuai dianalisis dari", opsi:["kenaikan harga tanah","dividen dari investasi saham","gaji debitur sebagai karyawan","perputaran piutang dagang dan persediaan menjadi kas","penjualan aset tetap"], kunci:4, pembahasan:"Kunci benar karena KMK perdagangan berputar melalui siklus kas dari piutang dan persediaan. Harga tanah, dividen, gaji karyawan, dan penjualan aset tetap bukan sumber pelunasan yang sesuai untuk KMK perdagangan."},
{id:"AK-036", modul:"analisis-kredit", kategori:"Arus Kas & Kapasitas Bayar", level:2, soal:"DSCR sebesar 1,2 kali artinya", opsi:["arus kas tersedia 1,2 kali kewajiban cicilan sehingga terdapat margin pengaman 20 persen","cicilan 1,2 kali arus kas","laba bersih 120 persen dari penjualan","utang 1,2 kali ekuitas","bunga 1,2 kali pokok"], kunci:0, pembahasan:"Kunci benar karena DSCR membandingkan arus kas yang tersedia dengan kewajiban pembayaran utang; 1,2x berarti kas 20 persen di atas kewajiban. Pengecoh salah karena membalik pembilang-penyebut atau mencampuradukkan dengan rasio profitabilitas dan leverage."},
{id:"AK-037", modul:"analisis-kredit", kategori:"Arus Kas & Kapasitas Bayar", level:2, soal:"Perusahaan mencatat laba bersih besar tetapi kas operasional kecil. Sikap analis yang tepat adalah", opsi:["langsung menyetujui karena laba besar","mewaspadai kualitas laba dan menelusuri penumpukan piutang atau persediaan","menaikkan plafon karena laba tinggi","mengabaikan arus kas karena laba lebih penting","menolak tanpa analisis lanjutan"], kunci:1, pembahasan:"Kunci benar karena laba akuntansi dapat terbentuk tanpa kas masuk, misalnya penjualan kredit yang belum tertagih. Laba besar bukan alasan persetujuan otomatis maupun kenaikan plafon, dan penolakan tanpa telaah bukan analisis yang baik."},
{id:"AK-038", modul:"analisis-kredit", kategori:"Arus Kas & Kapasitas Bayar", level:2, soal:"Untuk kredit investasi pembangunan pabrik, kemampuan bayar paling tepat diuji melalui", opsi:["laporan keuangan historis saja","proyeksi arus kas proyek selama umur kredit","nilai agunan tanah pabrik","jumlah karyawan yang akan direkrut","besarnya modal disetor"], kunci:2, pembahasan:"Kunci benar karena kredit investasi dilunasi dari kas yang dihasilkan proyek di masa depan sehingga proyeksi arus kas menjadi uji utama. Data historis belum mencerminkan proyek baru, sedangkan agunan, karyawan, dan modal disetor bukan sumber pelunasan."},
{id:"AK-039", modul:"analisis-kredit", kategori:"Arus Kas & Kapasitas Bayar", level:3, soal:"Usaha penggilingan padi hanya beromzet besar pada musim panen. Struktur pembayaran yang paling sesuai dengan pola arus kas tersebut adalah", opsi:["angsuran bulanan tetap sepanjang tahun","angsuran disesuaikan pola kas, misalnya masa tenggang saat paceklik dan pembayaran besar saat panen","pelunasan sekaligus di awal","bunga dibayar di muka","cicilan pokok tanpa bunga"], kunci:3, pembahasan:"Kunci benar karena struktur pembayaran harus mengikuti pola kas agar debitur tidak gagal bayar di luar musim. Angsuran bulanan tetap memaksa pembayaran saat kas kosong, sedangkan pelunasan di awal dan bunga di muka tidak sesuai dengan usaha musiman."},
{id:"AK-040", modul:"analisis-kredit", kategori:"Arus Kas & Kapasitas Bayar", level:3, soal:"Arus kas bebas (free cash flow) calon debitur negatif selama dua tahun berturut-turut karena ekspansi agresif. Kesimpulan analisis kapasitas bayar yang tepat adalah", opsi:["kemampuan bayar kuat karena ekspansi","kemampuan bayar lemah sehingga kredit baru sebaiknya ditolak atau plafon diturunkan hingga kas membaik","arus kas negatif tidak relevan bagi analis","ekspansi selalu menambah kemampuan bayar","bank wajib menyetujui karena usaha berkembang"], kunci:4, pembahasan:"Kunci benar karena kas bebas negatif berarti kas tidak cukup menutup kewajiban setelah belanja modal. Ekspansi bukan bukti kemampuan bayar, arus kas sangat relevan, dan tidak ada kewajiban bank menyetujui kredit."},
{id:"AK-041", modul:"analisis-kredit", kategori:"Arus Kas & Kapasitas Bayar", level:3, soal:"Dalam menganalisis kapasitas bayar, analis harus memisahkan arus kas operasi dari arus kas pendanaan karena", opsi:["arus kas pendanaan lebih besar","pelunasan kredit yang sehat harus berasal dari operasi usaha, bukan dari utang baru yang hanya menggali lubang tutup lubang","arus kas operasi sulit dihitung","regulator melarang melihat arus kas pendanaan","arus kas pendanaan selalu negatif"], kunci:0, pembahasan:"Kunci benar karena pelunasan dari utang baru menandakan pembiayaan gali lubang tutup lubang dan memperbesar risiko gagal bayar. Besar-kecilnya arus kas pendanaan bukan alasan pemisahan, tidak ada larangan melihatnya, dan arus kas pendanaan tidak selalu negatif."},
{id:"AK-042", modul:"analisis-kredit", kategori:"Jenis Jaminan", level:1, soal:"Jaminan fidusia menurut UU No. 42 Tahun 1999 adalah", opsi:["jaminan atas tanah dan bangunan","pengalihan hak kepemilikan atas benda dengan kepercayaan, di mana benda tetap dikuasai pemberi fidusia","penyerahan benda bergerak kepada kreditur","jaminan berupa deposito berjangka","jaminan pribadi dari direksi"], kunci:1, pembahasan:"Kunci benar karena ciri fidusia adalah pengalihan hak milik secara kepercayaan sedangkan penguasaan tetap pada debitur. Jaminan tanah adalah hak tanggungan, penyerahan benda kepada kreditur adalah gadai, sedangkan deposito dan jaminan pribadi bukan fidusia."},
{id:"AK-043", modul:"analisis-kredit", kategori:"Jenis Jaminan", level:1, soal:"Untuk menjaminkan tanah bersertifikat sebagai agunan kredit, lembaga jaminan yang tepat adalah", opsi:["fidusia","gadai","hak tanggungan menurut UU No. 4 Tahun 1996","cessie","hipotek kapal laut"], kunci:2, pembahasan:"Kunci benar karena hak tanggungan adalah lembaga jaminan khusus atas tanah menurut UU 4/1996. Fidusia untuk benda bergerak, gadai mensyaratkan penyerahan benda, cessie untuk piutang, dan hipotek untuk kapal laut."},
{id:"AK-044", modul:"analisis-kredit", kategori:"Jenis Jaminan", level:1, soal:"Ciri utama gadai sebagai lembaga jaminan adalah", opsi:["objeknya tanah","benda jaminan diserahkan dan dikuasai kreditur","tanpa penyerahan benda","objeknya piutang","didaftarkan ke kantor pertanahan"], kunci:3, pembahasan:"Kunci benar karena gadai mensyaratkan benda bergerak diserahkan kepada kreditur. Objek tanah memakai hak tanggungan, tanpa penyerahan adalah fidusia, objek piutang memakai cessie, dan pendaftaran tanah bukan ciri gadai."},
{id:"AK-045", modul:"analisis-kredit", kategori:"Jenis Jaminan", level:1, soal:"Cessie sebagai pengamanan kredit berarti", opsi:["penyerahan emas batangan","pengalihan piutang debitur kepada bank sebagai jaminan","penjaminan tanah","penanggungan oleh pihak ketiga","penyimpanan BPKB di bank"], kunci:4, pembahasan:"Kunci benar karena cessie adalah pengalihan hak atas piutang. Emas dan BPKB lazimnya digadaikan atau difidusiakan, tanah memakai hak tanggungan, dan penanggungan pihak ketiga adalah borgtocht atau garansi."},
{id:"AK-046", modul:"analisis-kredit", kategori:"Jenis Jaminan", level:2, soal:"Persediaan barang dagangan yang perputarannya cepat paling tepat dijaminkan dengan", opsi:["fidusia atas persediaan karena barang tetap dikuasai debitur untuk diperdagangkan","hak tanggungan","gadai karena barang diserahkan","hipotek","tanpa pengikatan"], kunci:0, pembahasan:"Kunci benar karena fidusia memungkinkan barang tetap di gudang debitur untuk dijual, dengan kewajiban mengganti. Hak tanggungan untuk tanah, gadai tidak cocok karena barang harus terus diperdagangkan, dan tanpa pengikatan bank tidak punya hak preferensi."},
{id:"AK-047", modul:"analisis-kredit", kategori:"Jenis Jaminan", level:2, soal:"Sertifikat Hak Milik atas tanah yang diagunkan dibebani dengan", opsi:["Akta Pemberian Hak Tanggungan (APHT) yang didaftarkan ke kantor pertanahan","akta fidusia","surat gadai","kuitansi jual beli","girik tanpa pendaftaran"], kunci:1, pembahasan:"Kunci benar karena pembebanan hak tanggungan wajib dengan APHT dan didaftarkan untuk melahirkan hak preferensi. Akta fidusia dan surat gadai bukan untuk tanah, sedangkan kuitansi dan girik tanpa pendaftaran tidak memberi kedudukan preferen."},
{id:"AK-048", modul:"analisis-kredit", kategori:"Jenis Jaminan", level:3, soal:"Keunggulan kreditur pemegang hak tanggungan atau fidusia terdaftar dibandingkan kreditur konkuren adalah", opsi:["dibebaskan dari pajak","mendapat bunga lebih rendah","memiliki hak preferensi, yaitu didahulukan dalam pelunasan dari hasil eksekusi objek jaminan","tidak perlu menagih","otomatis menjadi pemilik agunan"], kunci:2, pembahasan:"Kunci benar karena pendaftaran melahirkan hak yang didahulukan atas kreditur lain. Pengecoh salah karena tidak ada pembebasan pajak, bunga tidak terkait jenis jaminan, penagihan tetap diperlukan, dan kreditur tidak otomatis menjadi pemilik."},
{id:"AK-049", modul:"analisis-kredit", kategori:"Jenis Jaminan", level:3, soal:"Agunan berupa persediaan yang nilainya fluktuatif mengikuti harga pasar. Mitigasi yang tepat bagi analis adalah", opsi:["menerima nilai agunan apa adanya","menggunakan nilai pasar tertinggi","menerapkan haircut atas nilai taksasi, memantau stok berkala, dan menjaga coverage ratio yang cukup","tidak memerlukan agunan","menilai setahun sekali"], kunci:3, pembahasan:"Kunci benar karena haircut mengantisipasi penurunan harga, monitoring memastikan stok benar ada, dan coverage ratio menjaga kecukupan pengaman. Menerima apa adanya dan memakai harga tertinggi mengabaikan risiko fluktuasi, sedangkan tanpa agunan atau penilaian jarang memperlemah posisi bank."},
{id:"AK-050", modul:"analisis-kredit", kategori:"Kolektibilitas", level:1, soal:"Menurut POJK No. 40/POJK.03/2019, kualitas aset produktif berupa kredit digolongkan ke dalam kolektibilitas", opsi:["Lancar dan Macet saja","Lancar, Kurang Lancar, Macet","Lancar, Dalam Perhatian Khusus, Kurang Lancar, Diragukan, Macet","A, B, C, D, E","Prioritas dan Non-prioritas"], kunci:4, pembahasan:"Kunci benar karena POJK 40/2019 menetapkan lima kategori kolektibilitas tersebut. Pengecoh salah karena menggabungkan atau menghilangkan kategori, memakai kode huruf, atau memakai istilah yang tidak dikenal dalam ketentuan."},
{id:"AK-051", modul:"analisis-kredit", kategori:"Kolektibilitas", level:1, soal:"Debitur menunggak pembayaran selama 45 hari. Dalam praktik umum perbankan, kolektibilitas kredit tersebut adalah", opsi:["Dalam Perhatian Khusus","Lancar","Kurang Lancar","Diragukan","Macet"], kunci:0, pembahasan:"Kunci benar karena tunggakan 1 sampai 90 hari lazim digolongkan Dalam Perhatian Khusus. Belum Kurang Lancar (91-120 hari), Diragukan (121-180 hari), atau Macet (di atas 180 hari), dan tidak lagi Lancar karena sudah ada tunggakan."},
{id:"AK-052", modul:"analisis-kredit", kategori:"Kolektibilitas", level:3, soal:"Debitur menunggak 100 hari, tetapi nilai agunan masih menutupi seluruh baki debet. Kolektibilitas yang tepat menurut praktik umum adalah", opsi:["Lancar karena agunan cukup","Kurang Lancar, karena penggolongan terutama didasarkan pada ketepatan pembayaran, bukan kecukupan agunan","Dalam Perhatian Khusus","Diragukan","Macet"], kunci:1, pembahasan:"Kunci benar karena tunggakan 91-120 hari masuk Kurang Lancar dan penilaian kolektibilitas bertumpu pada pembayaran, bukan agunan. Agunan yang cukup tidak mengubah keterlambatan faktual menjadi Lancar atau DPK."},
{id:"AK-053", modul:"analisis-kredit", kategori:"Kolektibilitas", level:3, soal:"Debitur menunggak 200 hari tanpa prospek pembayaran. Kolektibilitas yang tepat adalah", opsi:["Dalam Perhatian Khusus","Kurang Lancar","Diragukan","Macet, karena tunggakan telah melampaui 180 hari","Lancar"], kunci:2, pembahasan:"Kunci benar karena tunggakan di atas 180 hari menurut praktik umum digolongkan Macet. Kategori DPK, Kurang Lancar, dan Diragukan berlaku untuk tunggakan yang lebih pendek, sedangkan Lancar mensyaratkan tidak ada tunggakan."},
{id:"AK-054", modul:"analisis-kredit", kategori:"Kolektibilitas", level:3, soal:"Debitur dengan plafon di atas Rp5 miliar tercatat kolektibilitas 3 di bank lain, tetapi membayar lancar di bank analis. Penilaian kualitas yang tepat adalah", opsi:["otomatis mengikuti kolektibilitas 3 bank lain","tetap Lancar tanpa analisis","menilai prospek usaha, kinerja, dan kemampuan bayar debitur secara menyeluruh karena untuk plafon besar penilaian tidak hanya dari ketepatan pembayaran","langsung ditolak","menaikkan kolektibilitas menjadi 5"], kunci:3, pembahasan:"Kunci benar karena untuk kredit di atas Rp5 miliar, POJK 40/2019 menilai kualitas dari prospek usaha, kinerja, dan kemampuan bayar, bukan sekadar ketepatan pembayaran. Mengikuti otomatis, menetapkannya Lancar tanpa telaah, menolak langsung, atau menaikkan ke Macet bukan penilaian yang tepat."},
{id:"AK-055", modul:"analisis-kredit", kategori:"Restrukturisasi", level:2, soal:"Menurut POJK No. 40/POJK.03/2019, restrukturisasi kredit adalah", opsi:["penghapusan kredit macet","penjualan kredit ke pihak lain","penagihan melalui pengadilan","upaya perbaikan yang dilakukan dalam kegiatan perkreditan terhadap debitur yang mengalami kesulitan memenuhi kewajibannya","penutupan fasilitas kredit"], kunci:4, pembahasan:"Kunci benar karena definisi tersebut menegaskan restrukturisasi sebagai upaya perbaikan bagi debitur yang kesulitan, bukan penghapusan. Penghapusan, penjualan kredit, penagihan litigasi, dan penutupan fasilitas adalah langkah penyelesaian atau penghentian, bukan restrukturisasi."},
{id:"AK-056", modul:"analisis-kredit", kategori:"Restrukturisasi", level:3, soal:"Restrukturisasi tepat diberikan kepada debitur yang", opsi:["masih memiliki prospek usaha yang baik tetapi mengalami kesulitan likuiditas sementara","sudah tidak beroperasi","beritikad tidak baik","menolak membayar","telah dinyatakan pailit"], kunci:0, pembahasan:"Kunci benar karena restrukturisasi ditujukan bagi debitur yang usahanya masih viable namun terkendala sementara. Usaha yang berhenti, debitur beritikad buruk, menolak bayar, atau pailit tidak memenuhi syarat dan lebih tepat diselesaikan melalui agunan atau litigasi."},
{id:"AK-057", modul:"analisis-kredit", kategori:"Mitigasi Risiko", level:2, soal:"Berikut ini yang termasuk mitigasi risiko kredit adalah", opsi:["memperbesar plafon tanpa analisis","agunan yang cukup, asuransi, covenant dalam perjanjian, dan monitoring berkala","mempercepat pencairan","menghapus kewajiban pelaporan","menurunkan suku bunga untuk semua debitur"], kunci:1, pembahasan:"Kunci benar karena keempatnya adalah lapisan pengaman risiko yang lazim. Memperbesar plafon tanpa analisis, mempercepat pencairan, menghapus pelaporan, dan menurunkan bunga massal justru menambah risiko."},
{id:"AK-058", modul:"analisis-kredit", kategori:"Mitigasi Risiko", level:3, soal:"Covenant dalam perjanjian kredit berfungsi untuk", opsi:["menambah keuntungan bank","membatasi tindakan debitur yang dapat merugikan bank, misalnya pembatasan pembagian dividen atau penambahan utang","mempercepat pelunasan","menghapus agunan","mengganti direksi debitur"], kunci:2, pembahasan:"Kunci benar karena covenant adalah janji kontraktual yang menjaga kondisi keuangan debitur tetap sehat. Tujuannya bukan menambah keuntungan bank, mempercepat pelunasan, menghapus agunan, atau mengganti direksi."},
{id:"AK-059", modul:"analisis-kredit", kategori:"Mitigasi Risiko", level:3, soal:"Early warning system dalam pengelolaan kredit bertujuan", opsi:["menambah jumlah debitur","mendeteksi dini gejala penurunan kualitas kredit agar dapat diambil tindakan penyelamatan tepat waktu","mempercepat proses pencairan","mengurangi jumlah analis","menaikkan target kredit"], kunci:3, pembahasan:"Kunci benar karena deteksi dini memungkinkan rescheduling, reconditioning, atau restructuring sebelum kredit memburuk. Menambah debitur, mempercepat pencairan, mengurangi analis, dan menaikkan target bukan fungsi sistem peringatan dini."},
{id:"AK-060", modul:"analisis-kredit", kategori:"Kolektibilitas", level:2, soal:"Menurut Pasal 31 POJK No. 40/POJK.03/2019, penilaian kualitas kredit dengan plafon sampai dengan Rp5 miliar dapat dilakukan hanya berdasarkan", opsi:["prospek usaha","kinerja debitur","laporan keuangan audit","ketepatan pembayaran kembali","nilai agunan"], kunci:4, pembahasan:"Kunci benar karena ketentuan tersebut menyederhanakan penilaian kredit kecil-menengah dengan satu pilar, yaitu ketepatan pembayaran. Prospek usaha dan kinerja debitur menjadi pilar penilaian untuk plafon di atas Rp5 miliar, sedangkan laporan audit dan nilai agunan bukan dasar tunggal menurut pasal ini."},
{id:"SR-001", modul:"slik-rasio-hitungan", kategori:"SLIK / iDeb", level:1, soal:"Sistem Layanan Informasi Keuangan (SLIK) OJK menyediakan", opsi:["informasi debitur individual (iDeb) berupa identitas, fasilitas kredit, plafon, baki debet, dan kolektibilitas","suku bunga acuan Bank Indonesia","kurs valuta asing harian","laporan keuangan bank umum","daftar agen Laku Pandai"], kunci:0, pembahasan:"Kunci benar karena SLIK menghimpun informasi debitur individual dari lembaga jasa keuangan untuk menilai riwayat kredit. Suku bunga acuan, kurs, laporan keuangan bank, dan daftar agen bukan isi SLIK."},
{id:"SR-002", modul:"slik-rasio-hitungan", kategori:"SLIK / iDeb", level:1, soal:"Calon debitur dapat memperoleh informasi debitur individual (iDeb) miliknya melalui", opsi:["kantor kelurahan","aplikasi idebku.ojk.go.id atau datang langsung ke kantor OJK","kantor pos","bank tempat menabung tanpa identitas","media sosial OJK"], kunci:1, pembahasan:"Kunci benar karena OJK menyediakan layanan iDeb melalui situs idebku.ojk.go.id dan layanan tatap muka di kantor OJK dengan verifikasi identitas. Kelurahan, kantor pos, bank tanpa identitas, dan media sosial bukan kanal resmi iDeb."},
{id:"SR-003", modul:"slik-rasio-hitungan", kategori:"SLIK / iDeb", level:2, soal:"Pada laporan iDeb SLIK, kolom kolektibilitas berisi angka 1 sampai 5 yang menunjukkan", opsi:["jumlah fasilitas kredit","besarnya plafon","kualitas kredit dari Lancar sampai Macet","suku bunga kredit","jangka waktu kredit"], kunci:2, pembahasan:"Kunci benar karena angka 1 sampai 5 memetakan lima kategori kolektibilitas menurut POJK 40/2019. Jumlah fasilitas, plafon, suku bunga, dan tenor ditampilkan pada kolom lain dalam laporan iDeb."},
{id:"SR-004", modul:"slik-rasio-hitungan", kategori:"SLIK / iDeb", level:2, soal:"SLIK dalam praktik perbankan saat ini menggantikan fungsi", opsi:["Sistem Kliring Nasional","SKNBI","RTGS","BI Checking melalui Sistem Informasi Debitur (SID)","LPS"], kunci:3, pembahasan:"Kunci benar karena sebelum SLIK, informasi riwayat kredit disediakan Bank Indonesia melalui SID yang dikenal sebagai BI Checking. Kliring, SKNBI, dan RTGS adalah sistem pembayaran, sedangkan LPS adalah penjamin simpanan."},
{id:"SR-005", modul:"slik-rasio-hitungan", kategori:"SLIK / iDeb", level:3, soal:"Calon debitur tercatat kolektibilitas 3 di satu bank dua tahun lalu, tetapi 12 bulan terakhir seluruh fasilitasnya Lancar. Sikap analis yang tepat adalah", opsi:["menolak otomatis karena pernah kol 3","mengabaikan catatan lama sepenuhnya","menilai ulang prospek usaha, kinerja, dan kemampuan bayar saat ini karena catatan lama menjadi perhatian namun bukan vonis otomatis","meminta agunan 200 persen","menaikkan suku bunga sebagai hukuman"], kunci:4, pembahasan:"Kunci benar karena riwayat buruk adalah sinyal kewaspadaan, tetapi keputusan harus didasarkan pada kondisi terkini debitur. Penolakan otomatis mengabaikan perbaikan yang terbukti 12 bulan, sedangkan mengabaikan catatan atau menghukum dengan agunan dan bunga bukan analisis yang proporsional."},
{id:"SR-006", modul:"slik-rasio-hitungan", kategori:"Membaca Laporan Keuangan", level:1, soal:"Neraca perusahaan menunjukkan", opsi:["posisi aset, liabilitas, dan ekuitas pada tanggal tertentu","laba rugi selama setahun","arus kas masuk dan keluar","jumlah karyawan","harga saham perusahaan"], kunci:0, pembahasan:"Kunci benar karena neraca adalah potret posisi keuangan pada satu titik waktu. Laba rugi menunjukkan kinerja selama periode, arus kas menunjukkan pergerakan kas, sedangkan jumlah karyawan dan harga saham bukan isi neraca."},
{id:"SR-007", modul:"slik-rasio-hitungan", kategori:"Membaca Laporan Keuangan", level:1, soal:"Laporan laba rugi perusahaan menunjukkan", opsi:["posisi kas di bank","kinerja pendapatan, beban, dan laba selama satu periode","nilai aset tetap","jumlah utang","modal disetor"], kunci:1, pembahasan:"Kunci benar karena laba rugi merangkum kinerja operasional selama periode tertentu. Posisi kas, aset tetap, utang, dan modal disetor adalah unsur neraca."},
{id:"SR-008", modul:"slik-rasio-hitungan", kategori:"Membaca Laporan Keuangan", level:2, soal:"Perusahaan mencatat laba bersih positif, tetapi arus kas dari operasi negatif. Indikasi yang paling mungkin adalah", opsi:["perusahaan sangat sehat","laba berkualitas karena didukung kas","penumpukan piutang tak tertagih atau persediaan yang tidak laku","beban bunga terlalu kecil","pajak terlalu besar"], kunci:2, pembahasan:"Kunci benar karena laba tanpa kas masuk menandakan penjualan belum menjadi kas, lazimnya karena piutang membengkak atau persediaan menumpuk. Kondisi ini justru menandakan kualitas laba buruk, bukan kesehatan, dan tidak berkaitan dengan kecilnya bunga atau besarnya pajak."},
{id:"SR-009", modul:"slik-rasio-hitungan", kategori:"Membaca Laporan Keuangan", level:3, soal:"Window dressing dalam laporan keuangan berarti", opsi:["memasang iklan perusahaan","mempercantik tampilan laporan dengan manipulasi, misalnya menunda pencatatan utang agar rasio terlihat baik","mengganti auditor","mencetak laporan berwarna","membagikan dividen"], kunci:3, pembahasan:"Kunci benar karena window dressing adalah rekayasa tampilan laporan agar terlihat lebih baik dari kondisi sebenarnya. Iklan, ganti auditor, cetak berwarna, dan dividen bukan definisinya; analis harus mewaspadainya dengan verifikasi silang."},
{id:"SR-010", modul:"slik-rasio-hitungan", kategori:"Membaca Laporan Keuangan", level:3, soal:"Analis sebaiknya menganalisis laporan keuangan minimal tiga tahun terakhir, bukan satu tahun, karena", opsi:["regulator mewajibkan tiga tahun","satu tahun selalu salah","tren multi-tahun menunjukkan konsistensi kinerja dan pola usaha yang tidak terlihat dari satu titik waktu","laporan tiga tahun lebih tebal","auditor hanya mengaudit tiga tahun"], kunci:4, pembahasan:"Kunci benar karena tren mengungkap apakah pertumbuhan, margin, dan arus kas konsisten atau sekadar anomali satu tahun. Tidak ada kewajiban baku tiga tahun, satu tahun tidak selalu salah, dan ketebalan laporan bukan alasan analisis."},
{id:"SR-011", modul:"slik-rasio-hitungan", kategori:"Rasio Likuiditas", level:1, soal:"Perusahaan memiliki aset lancar Rp800 juta dan utang lancar Rp400 juta. Current ratio-nya adalah", opsi:["2,0 kali, dihitung dari 800 dibagi 400","0,5 kali, dihitung dari 400 dibagi 800","1,2 kali","3,0 kali","200 persen dari utang lancar dikurangi aset lancar"], kunci:0, pembahasan:"Kunci benar karena current ratio = aset lancar / utang lancar = 800 / 400 = 2,0 kali. Pengecoh 0,5 kali membalik pembilang dan penyebut, sedangkan 1,2 dan 3,0 tidak sesuai hasil pembagian."},
{id:"SR-012", modul:"slik-rasio-hitungan", kategori:"Rasio Likuiditas", level:1, soal:"Aset lancar Rp900 juta dan utang lancar Rp600 juta menghasilkan current ratio", opsi:["0,67 kali","1,5 kali, dihitung dari 900 dibagi 600","2,5 kali","300 juta","150 persen dikali utang"], kunci:1, pembahasan:"Kunci benar karena 900 / 600 = 1,5 kali. Pengecoh 0,67 membalik rumus, 2,5 salah hitung, 300 juta adalah modal kerja bukan rasio, dan rumusan terakhir tidak bermakna."},
{id:"SR-013", modul:"slik-rasio-hitungan", kategori:"Rasio Likuiditas", level:2, soal:"Aset lancar Rp450 juta dan utang lancar Rp300 juta. Current ratio dan interpretasinya adalah", opsi:["0,67 kali, likuiditas buruk","3,0 kali, sangat likuid","1,5 kali, cukup likuid karena aset lancar 50 persen di atas utang lancar","150 juta, likuid","2,0 kali"], kunci:2, pembahasan:"Kunci benar karena 450 / 300 = 1,5 kali yang berarti setiap Rp1 utang lancar dijamin Rp1,5 aset lancar. Pengecoh 0,67 membalik rumus, 3,0 dan 2,0 salah hitung, dan 150 juta adalah modal kerja, bukan rasio."},
{id:"SR-014", modul:"slik-rasio-hitungan", kategori:"Rasio Likuiditas", level:2, soal:"Aset lancar Rp350 juta dan utang lancar Rp500 juta menghasilkan current ratio 0,7 kali. Kesimpulan analis adalah", opsi:["likuiditas sangat baik","likuiditas buruk karena aset lancar tidak cukup menutupi utang lancar","perusahaan tidak punya utang","modal kerja positif 150 juta","rasio tidak dapat dihitung"], kunci:3, pembahasan:"Kunci benar karena rasio di bawah 1 berarti utang jangka pendek melebihi aset lancar. Pengecoh salah karena kondisi ini justru buruk, perusahaan jelas punya utang, modal kerja negatif 150 juta, dan rasio dapat dihitung."},
{id:"SR-015", modul:"slik-rasio-hitungan", kategori:"Rasio Likuiditas", level:3, soal:"Aset lancar Rp1.200 juta dan utang lancar Rp800 juta. Modal kerja bersih dan current ratio-nya adalah", opsi:["modal kerja Rp2.000 juta dan CR 2,5 kali","modal kerja Rp400 juta dan CR 0,67 kali","modal kerja Rp400 juta dan CR 1,5 kali","modal kerja negatif dan CR 1,5 kali","modal kerja Rp800 juta dan CR 1,0 kali"], kunci:4, pembahasan:"Kunci benar karena modal kerja = 1.200 - 800 = Rp400 juta dan CR = 1.200 / 800 = 1,5 kali. Pengecoh salah menjumlahkan, membalik rumus, atau salah menetapkan tanda modal kerja."},
{id:"SR-016", modul:"slik-rasio-hitungan", kategori:"Rasio Likuiditas", level:3, soal:"Current ratio perusahaan turun dari 2,0 kali menjadi 1,1 kali dalam setahun karena utang bank jangka pendek naik tajam untuk menutup operasional. Respons analis yang tepat adalah", opsi:["mewaspadai penurunan likuiditas dan menelusuri penyebab kebutuhan dana jangka pendek tersebut","mengabaikan karena masih di atas 1","langsung menolak tanpa telaah","menaikkan plafon agar likuiditas membaik","meminta agunan tambahan sebagai satu-satunya solusi"], kunci:0, pembahasan:"Kunci benar karena penurunan tajam akibat utang jangka pendek untuk operasional menandakan tekanan likuiditas yang harus ditelusuri. Mengabaikan, menolak tanpa telaah, menaikkan plafon, atau hanya meminta agunan bukan respons analisis yang tepat."},
{id:"SR-017", modul:"slik-rasio-hitungan", kategori:"Rasio Solvabilitas", level:1, soal:"Total liabilitas Rp900 juta dan total ekuitas Rp600 juta. Debt to equity ratio (DER) adalah", opsi:["0,67 kali","1,5 kali, dihitung dari 900 dibagi 600","2,5 kali","300 juta","150 persen dari ekuitas"], kunci:1, pembahasan:"Kunci benar karena DER = total liabilitas / total ekuitas = 900 / 600 = 1,5 kali. Pengecoh 0,67 membalik rumus, 2,5 salah hitung, dan 300 juta adalah selisih, bukan rasio."},
{id:"SR-018", modul:"slik-rasio-hitungan", kategori:"Rasio Solvabilitas", level:2, soal:"Total utang Rp400 juta dan ekuitas Rp800 juta menghasilkan DER 0,5 kali yang berarti", opsi:["leverage sangat tinggi","struktur modal konservatif karena utang hanya separuh ekuitas","perusahaan tidak punya utang","ekuitas negatif","risiko gagal bayar tinggi"], kunci:2, pembahasan:"Kunci benar karena DER 0,5 berarti setiap Rp1 ekuitas hanya dibebani Rp0,5 utang. Ini kebalikan dari leverage tinggi dan risiko gagal bayar tinggi, perusahaan jelas masih punya utang, dan ekuitasnya positif."},
{id:"SR-019", modul:"slik-rasio-hitungan", kategori:"Rasio Solvabilitas", level:3, soal:"Total utang Rp1.500 juta dan ekuitas Rp500 juta. DER dan implikasinya adalah", opsi:["0,33 kali, aman","1,0 kali, seimbang","2,0 kali, moderat","3,0 kali, leverage tinggi sehingga risiko keuangan meningkat","5,0 kali"], kunci:3, pembahasan:"Kunci benar karena 1.500 / 500 = 3,0 kali yang berarti utang tiga kali lipat ekuitas, sehingga bantalan modal tipis. Pengecoh 0,33 membalik rumus, sedangkan 1,0, 2,0, dan 5,0 tidak sesuai hasil perhitungan."},
{id:"SR-020", modul:"slik-rasio-hitungan", kategori:"Rasio Solvabilitas", level:3, soal:"DER perusahaan naik dari 1,0 kali menjadi 2,5 kali setelah menarik utang bank baru untuk ekspansi. Penilaian analis yang tepat adalah", opsi:["struktur modal membaik","tidak ada perubahan risiko","risiko keuangan meningkat karena porsi utang membesar sehingga kemampuan bayar harus diuji lebih ketat","ekspansi selalu menyehatkan","DER tidak relevan untuk kredit investasi"], kunci:4, pembahasan:"Kunci benar karena kenaikan DER berarti ketergantungan pada utang bertambah sehingga uji arus kas harus diperketat. Struktur modal justru memburuk, risiko berubah, ekspansi tidak selalu menyehatkan, dan DER tetap relevan untuk kredit investasi."},
{id:"SR-021", modul:"slik-rasio-hitungan", kategori:"Rasio Profitabilitas", level:1, soal:"Laba bersih Rp100 juta dan total aset Rp1.000 juta. Return on assets (ROA) adalah", opsi:["10 persen, dihitung dari 100 dibagi 1.000","1 persen","0,1 persen","1.000 persen","Rp900 juta"], kunci:0, pembahasan:"Kunci benar karena ROA = laba bersih / total aset = 100 / 1.000 = 10 persen. Pengecoh 1 persen dan 0,1 persen salah menempatkan desimal, 1.000 persen membalik skala, dan Rp900 juta adalah selisih, bukan rasio."},
{id:"SR-022", modul:"slik-rasio-hitungan", kategori:"Rasio Profitabilitas", level:1, soal:"Laba bersih Rp120 juta dan total ekuitas Rp800 juta. Return on equity (ROE) adalah", opsi:["6,67 persen","15 persen, dihitung dari 120 dibagi 800","25 persen","8 persen","Rp680 juta"], kunci:1, pembahasan:"Kunci benar karena ROE = laba bersih / ekuitas = 120 / 800 = 15 persen. Pengecoh 6,67 persen membalik rumus, 25 dan 8 persen salah hitung, dan Rp680 juta adalah selisih."},
{id:"SR-023", modul:"slik-rasio-hitungan", kategori:"Rasio Profitabilitas", level:1, soal:"Laba bersih Rp80 juta dan penjualan Rp800 juta. Net profit margin (NPM) adalah", opsi:["1 persen","10 persen, dihitung dari 80 dibagi 800","100 persen","720 juta","0,1 persen"], kunci:2, pembahasan:"Kunci benar karena NPM = laba bersih / penjualan = 80 / 800 = 10 persen. Pengecoh 1 persen dan 0,1 persen salah desimal, 100 persen berarti seluruh penjualan menjadi laba, dan 720 juta adalah selisih."},
{id:"SR-024", modul:"slik-rasio-hitungan", kategori:"Rasio Profitabilitas", level:2, soal:"Penjualan Rp2.000 juta dan laba bersih Rp200 juta menghasilkan NPM 10 persen. Interpretasi yang tepat adalah", opsi:["setiap Rp100 penjualan menghasilkan laba Rp10 sehingga efisiensi operasional cukup baik","perusahaan merugi","seluruh penjualan menjadi laba","margin tidak dapat dihitung","laba lebih besar dari penjualan"], kunci:3, pembahasan:"Kunci benar karena NPM 10 persen berarti 10 persen penjualan menjadi laba bersih. Perusahaan jelas tidak merugi, tidak seluruh penjualan menjadi laba, margin dapat dihitung, dan laba tidak melebihi penjualan."},
{id:"SR-025", modul:"slik-rasio-hitungan", kategori:"Rasio Profitabilitas", level:2, soal:"Total aset Rp2.500 juta dan laba bersih Rp200 juta. ROA adalah", opsi:["12,5 persen","2 persen","20 persen","8 persen, dihitung dari 200 dibagi 2.500","Rp2.300 juta"], kunci:4, pembahasan:"Kunci benar karena 200 / 2.500 = 8 persen. Pengecoh 12,5 persen membalik rumus, 2 dan 20 persen salah hitung, dan Rp2.300 juta adalah selisih."},
{id:"SR-026", modul:"slik-rasio-hitungan", kategori:"Rasio Profitabilitas", level:2, soal:"Ekuitas Rp500 juta dan laba bersih Rp125 juta. ROE adalah", opsi:["25 persen, dihitung dari 125 dibagi 500","4 persen","40 persen","0,25 persen","Rp375 juta"], kunci:0, pembahasan:"Kunci benar karena 125 / 500 = 25 persen. Pengecoh 4 persen membalik rumus, 40 dan 0,25 persen salah hitung, dan Rp375 juta adalah selisih."},
{id:"SR-027", modul:"slik-rasio-hitungan", kategori:"Rasio Profitabilitas", level:3, soal:"ROE perusahaan naik dari 15 persen menjadi 25 persen, tetapi kenaikan itu terjadi karena ekuitas menyusut akibat akumulasi rugi, bukan karena laba naik. Penilaian analis yang tepat adalah", opsi:["kinerja membaik karena ROE naik","kenaikan ROE semu dan justru menandakan permodalan melemah sehingga harus diwaspadai","ROE tidak perlu dianalisis","perusahaan layak diberi plafon besar","laba pasti naik"], kunci:1, pembahasan:"Kunci benar karena ROE yang naik akibat penyusutan penyebut adalah sinyal pelemahan modal, bukan perbaikan kinerja. Menganggapnya membaik, mengabaikan analisis, menaikkan plafon, atau menyimpulkan laba naik adalah kesalahan membaca rasio."},
{id:"SR-028", modul:"slik-rasio-hitungan", kategori:"Rasio Profitabilitas", level:3, soal:"NPM perusahaan turun dari 12 persen menjadi 7 persen dalam dua tahun. Langkah analisis yang tepat adalah", opsi:["mengabaikan karena masih positif","menyelidiki penyebabnya, misalnya kenaikan HPP atau beban operasional yang menggerus margin","langsung menolak kredit","meminta menaikkan harga jual","mengganti produk perusahaan"], kunci:2, pembahasan:"Kunci benar karena penurunan margin hampir separuh menandakan tekanan profitabilitas yang harus ditelusuri sumbernya. Mengabaikan, menolak tanpa telaah, atau memberi nasihat operasional bukan tugas analis pada tahap ini."},
{id:"SR-029", modul:"slik-rasio-hitungan", kategori:"Rasio Kemampuan Bayar", level:1, soal:"Debt service coverage ratio (DSCR) mengukur", opsi:["perputaran persediaan","kemampuan arus kas yang tersedia untuk menutupi kewajiban cicilan utang","perputaran piutang","tingkat pengembalian aset","likuiditas jangka pendek"], kunci:3, pembahasan:"Kunci benar karena DSCR membandingkan kas yang tersedia dengan debt service (pokok plus bunga). Perputaran persediaan dan piutang adalah rasio aktivitas, pengembalian aset adalah ROA, dan likuiditas jangka pendek diukur current ratio."},
{id:"SR-030", modul:"slik-rasio-hitungan", kategori:"Rasio Kemampuan Bayar", level:2, soal:"Arus kas tersedia Rp600 juta dan total cicilan utang setahun Rp500 juta. DSCR adalah", opsi:["0,83 kali","1,0 kali","1,5 kali","2,0 kali","1,2 kali, dihitung dari 600 dibagi 500"], kunci:4, pembahasan:"Kunci benar karena 600 / 500 = 1,2 kali. Pengecoh 0,83 membalik rumus, sedangkan 1,0, 1,5, dan 2,0 tidak sesuai hasil perhitungan."},
{id:"SR-031", modul:"slik-rasio-hitungan", kategori:"Rasio Kemampuan Bayar", level:1, soal:"Kas tersedia Rp480 juta dan cicilan Rp400 juta menghasilkan DSCR", opsi:["1,2 kali, dihitung dari 480 dibagi 400","0,83 kali","1,0 kali","80 juta","2,0 kali"], kunci:0, pembahasan:"Kunci benar karena 480 / 400 = 1,2 kali. Pengecoh 0,83 membalik rumus, 1,0 dan 2,0 salah hitung, dan 80 juta adalah selisih kas, bukan rasio."},
{id:"SR-032", modul:"slik-rasio-hitungan", kategori:"Rasio Kemampuan Bayar", level:3, soal:"DSCR calon debitur hanya 0,9 kali. Kesimpulan analisis yang tepat adalah", opsi:["kemampuan bayar sangat kuat","arus kas tidak cukup menutupi cicilan sehingga kredit sebaiknya ditolak atau plafon diturunkan","DSCR di bawah 1 tidak masalah","bank wajib menyetujui","cicilan pasti terbayar dari agunan"], kunci:1, pembahasan:"Kunci benar karena DSCR di bawah 1 berarti kas tersedia lebih kecil dari kewajiban, sehingga risiko gagal bayar tinggi. Menganggapnya kuat, mengabaikan, mewajibkan persetujuan, atau mengandalkan agunan sebagai sumber pelunasan adalah kesalahan analisis."},
{id:"SR-033", modul:"slik-rasio-hitungan", kategori:"Angsuran & Bunga", level:1, soal:"Pinjaman Rp120 juta, bunga flat 12 persen per tahun, tenor 12 bulan. Total bunga dan angsuran bulanannya adalah", opsi:["bunga Rp7,2 juta dan angsuran Rp10,6 juta","bunga Rp12 juta dan angsuran Rp10 juta","bunga Rp14,4 juta dan angsuran Rp11,2 juta per bulan","bunga Rp28,8 juta dan angsuran Rp12,4 juta","bunga Rp1,2 juta dan angsuran Rp9 juta"], kunci:2, pembahasan:"Kunci benar karena bunga flat = 120 juta x 12 persen = Rp14,4 juta; total pinjaman Rp134,4 juta dibagi 12 = Rp11,2 juta per bulan. Pengecoh salah menghitung persentase atau tenor."},
{id:"SR-034", modul:"slik-rasio-hitungan", kategori:"Angsuran & Bunga", level:2, soal:"Dengan tingkat bunga nominal yang sama, total bunga yang dibayar debitur pada sistem anuitas (efektif) dibandingkan sistem flat adalah", opsi:["sama persis","lebih besar","lebih kecil, karena bunga dihitung dari sisa pokok yang terus menurun","nol","dua kali lipat"], kunci:3, pembahasan:"Kunci benar karena pada sistem efektif bunga hanya dikenakan atas sisa pokok, sedangkan flat mengenakan bunga atas pokok awal selama tenor. Total bunga tidak sama, tidak lebih besar, tidak nol, dan tidak dua kali lipat."},
{id:"SR-035", modul:"slik-rasio-hitungan", kategori:"Angsuran & Bunga", level:2, soal:"Pinjaman Rp100 juta, bunga efektif 1 persen per bulan, tenor 12 bulan, sistem anuitas. Angsuran bulanannya adalah", opsi:["Rp9,33 juta","Rp8,33 juta","Rp10 juta","Rp7,5 juta","Rp8,88 juta"], kunci:4, pembahasan:"Kunci benar karena angsuran anuitas = 100 juta x 1 persen / (1 - 1,01 pangkat -12) = 1 juta / 0,1126 = Rp8,88 juta. Total pembayaran Rp106,62 juta sehingga bunganya Rp6,62 juta. Pengecoh Rp9,33 juta adalah angsuran sistem flat, sedangkan lainnya salah hitung."},
{id:"SR-036", modul:"slik-rasio-hitungan", kategori:"Angsuran & Bunga", level:2, soal:"Pada sistem bunga efektif menurun (sliding rate), pola angsuran yang terjadi adalah", opsi:["angsuran total menurun karena porsi bunga mengecil mengikuti sisa pokok","angsuran total tetap","angsuran total naik","hanya bunga yang dibayar","pokok tidak pernah berkurang"], kunci:0, pembahasan:"Kunci benar karena dengan pokok angsuran tetap, bunga yang dihitung dari sisa pokok akan mengecil setiap bulan. Angsuran tetap adalah ciri anuitas, bukan sliding rate; pola naik, hanya bunga, dan pokok tak berkurang bukan ciri sistem ini."},
{id:"SR-037", modul:"slik-rasio-hitungan", kategori:"Angsuran & Bunga", level:3, soal:"Pinjaman Rp120 juta tenor 12 bulan. Dengan bunga flat 12 persen per tahun total bunganya Rp14,4 juta. Jika memakai bunga efektif 12 persen per tahun sistem anuitas, total bunganya adalah", opsi:["Rp14,4 juta, sama dengan flat","Rp20 juta","Rp7,94 juta, lebih kecil karena bunga dihitung dari sisa pokok","Rp28,8 juta","Rp1,2 juta"], kunci:1, pembahasan:"Kunci benar karena angsuran anuitas = 120 juta x 1 persen / 0,1126 = Rp10,66 juta; total Rp127,94 juta sehingga bunga = Rp7,94 juta. Verifikasi: 10,66 x 12 = 127,94; 127,94 - 120 = 7,94. Pengecoh salah karena menyamakan dengan flat atau salah hitung."},
{id:"SR-038", modul:"slik-rasio-hitungan", kategori:"Angsuran & Bunga", level:3, soal:"Praktik umum perbankan menyatakan beban bunga efektif pinjaman dengan bunga flat 12 persen per tahun tenor 12 bulan mendekati", opsi:["12 persen juga","6 persen","dua kali lipat bunga flat, sekitar 21-22 persen per tahun, karena bunga dibayar atas pokok awal padahal pokok telah menurun","36 persen","0 persen"], kunci:2, pembahasan:"Kunci benar karena pada flat, debitur membayar bunga atas pokok penuh selama 12 bulan meski pokok berangsur lunas, sehingga biaya efektifnya hampir dua kali nominal. Bukan 12 persen, bukan setengahnya, dan bukan 36 persen."},
{id:"SR-039", modul:"slik-rasio-hitungan", kategori:"Angsuran & Bunga", level:3, soal:"Grace period dalam struktur kredit berarti", opsi:["penghapusan bunga","masa tenggang penundaan pembayaran pokok di awal kredit, cocok untuk proyek yang belum menghasilkan kas","diskon pelunasan","perpanjangan otomatis","pembebasan agunan"], kunci:3, pembahasan:"Kunci benar karena grace period memberi waktu proyek mencapai tahap menghasilkan sebelum cicilan pokok dimulai. Ini bukan penghapusan bunga, diskon, perpanjangan otomatis, atau pembebasan agunan."},
{id:"SR-040", modul:"slik-rasio-hitungan", kategori:"Angsuran & Bunga", level:3, soal:"Struktur balloon payment berarti", opsi:["angsuran sama besar setiap bulan","angsuran kecil selama tenor dan pelunasan besar di akhir","pembayaran dengan balon","bunga dibayar di muka","tanpa angsuran"], kunci:4, pembahasan:"Kunci benar karena balloon payment menunda sebagian besar pokok ke pembayaran terakhir. Angsuran sama adalah anuitas, sedangkan bunga di muka, tanpa angsuran, dan arti harfiah balon bukan definisinya; risikonya adalah kebutuhan refinancing di akhir."},
{id:"SR-041", modul:"slik-rasio-hitungan", kategori:"Rasio Kesehatan Bank", level:1, soal:"Giro Rp2 triliun, tabungan Rp5 triliun, deposito Rp3 triliun, dan simpanan antarbank Rp1 triliun. Dana pihak ketiga (DPK) bank tersebut adalah", opsi:["Rp10 triliun, karena DPK = giro + tabungan + deposito tanpa antarbank","Rp11 triliun","Rp9 triliun","Rp6 triliun","Rp3 triliun"], kunci:0, pembahasan:"Kunci benar karena DPK = 2 + 5 + 3 = Rp10 triliun; simpanan antarbank bukan dana masyarakat sehingga dikecualikan. Pengecoh salah karena memasukkan antarbank atau salah menjumlahkan."},
{id:"SR-042", modul:"slik-rasio-hitungan", kategori:"Rasio Kesehatan Bank", level:1, soal:"Total kredit Rp100 triliun dan kredit bermasalah Rp3 triliun. NPL gross bank tersebut adalah", opsi:["0,3 persen","3 persen, dihitung dari 3 dibagi 100 tanpa dikurangi penyisihan","30 persen","97 persen","103 persen"], kunci:1, pembahasan:"Kunci benar karena NPL gross resmi OJK = kredit bermasalah / total kredit = 3 persen, tanpa dikurangi CKPN. Pengecoh salah desimal, salah skala, atau menghitung kredit lancar."},
{id:"SR-043", modul:"slik-rasio-hitungan", kategori:"Rasio Kesehatan Bank", level:2, soal:"Beban operasional Rp80 miliar dan pendapatan operasional Rp100 miliar. BOPO bank tersebut adalah", opsi:["125 persen","20 persen","80 persen, berarti semakin rendah semakin efisien","180 persen","Rp20 miliar"], kunci:2, pembahasan:"Kunci benar karena BOPO = 80 / 100 = 80 persen; semakin rendah berarti semakin efisien. Pengecoh 125 persen membalik rumus, 20 persen salah hitung, 180 persen menjumlahkan, dan Rp20 miliar adalah selisih."},
{id:"SR-044", modul:"slik-rasio-hitungan", kategori:"Rasio Kesehatan Bank", level:2, soal:"Pendapatan bunga bersih Rp120 miliar dan rata-rata aset produktif Rp2.000 miliar. NIM bank tersebut adalah", opsi:["16,7 persen","0,6 persen","12 persen","6 persen, dihitung dari 120 dibagi 2.000","Rp1.880 miliar"], kunci:3, pembahasan:"Kunci benar karena NIM = pendapatan bunga bersih / rata-rata aset produktif = 120 / 2.000 = 6 persen. Pengecoh 16,7 persen membalik rumus, 0,6 persen salah desimal, 12 persen salah hitung, dan Rp1.880 miliar adalah selisih."},
{id:"SR-045", modul:"slik-rasio-hitungan", kategori:"Rasio Kesehatan Bank", level:3, soal:"Kredit yang disalurkan Rp9 triliun dan DPK Rp10 triliun menghasilkan LDR 90 persen. Interpretasi yang tepat adalah", opsi:["bank tidak menyalurkan kredit","likuiditas ketat karena hampir seluruh DPK tersalurkan menjadi kredit sehingga ruang ekspansi terbatas","bank kelebihan likuiditas","LDR tidak berkaitan dengan likuiditas","semakin tinggi LDR semakin likuid"], kunci:4, pembahasan:"Kunci benar karena LDR = 9 / 10 = 90 persen yang berarti intermediasi tinggi dan buffer likuiditas menipis. Bank jelas menyalurkan kredit, tidak kelebihan likuiditas, LDR berkaitan erat dengan likuiditas, dan LDR tinggi berarti kurang likuid, bukan sebaliknya."},
{id:"SK-001", modul:"studi-kasus", kategori:"Kasus UMKM", level:1, soal:"Warung kelontong milik Ibu Sari beromzet Rp60 juta per bulan dengan laba bersih Rp12 juta per bulan. Ia mengajukan KMK Rp50 juta dengan cicilan Rp5 juta per bulan. Keputusan analisis yang tepat adalah", opsi:["layak dipertimbangkan karena DSCR = 12 / 5 = 2,4 kali, arus kas jauh di atas cicilan","ditolak karena omzet terlalu kecil","ditolak karena warung bukan usaha prospektif","layak tanpa verifikasi","cicilan harus sama dengan laba"], kunci:0, pembahasan:"Kunci benar karena DSCR 2,4 kali menunjukkan kemampuan bayar sangat kuat. Omzet Rp60 juta bukan alasan penolakan untuk plafon Rp50 juta, warung kelontong adalah usaha riil, verifikasi tetap wajib, dan cicilan tidak harus sama dengan laba."},
{id:"SK-002", modul:"studi-kasus", kategori:"Kasus UMKM", level:1, soal:"Bengkel milik Bapak Budi beromzet Rp40 juta per bulan dengan laba Rp8 juta per bulan. Cicilan kredit yang diajukan Rp3 juta per bulan. Keputusan yang tepat adalah", opsi:["ditolak karena laba kecil","layak dipertimbangkan karena DSCR = 8 / 3 = 2,67 kali","plafon harus sama dengan omzet","bengkel tidak bankable","cicilan maksimal Rp8 juta"], kunci:1, pembahasan:"Kunci benar karena DSCR 2,67 kali menandakan arus kas hampir tiga kali cicilan. Laba Rp8 juta memadai untuk cicilan Rp3 juta, plafon tidak harus sama dengan omzet, dan bengkel adalah usaha yang bankable."},
{id:"SK-003", modul:"studi-kasus", kategori:"Kasus UMKM", level:1, soal:"Toko milik Bapak Agus mengajukan kredit Rp100 juta dengan agunan SHM senilai Rp300 juta yang dokumennya lengkap. Dari sisi agunan, kesimpulan yang tepat adalah", opsi:["tidak layak karena agunan terlalu besar","layak dari sisi agunan karena coverage = 300 / 100 = 3 kali","agunan harus pas Rp100 juta","SHM tidak bisa diagunkan","nilai agunan tidak penting"], kunci:2, pembahasan:"Kunci benar karena coverage 3 kali memberi pengaman yang sangat cukup. Agunan lebih besar bukan masalah, tidak harus pas dengan plafon, SHM adalah agunan yang lazim, dan nilai agunan tetap penting sebagai pengaman kedua."},
{id:"SK-004", modul:"studi-kasus", kategori:"Kasus UMKM", level:1, soal:"Hasil SLIK calon debitur menunjukkan seluruh fasilitasnya kolektibilitas 1 dan tidak pernah menunggak. Kesimpulan awal atas Character-nya adalah", opsi:["buruk","baik, karena riwayat pembayaran lancar mencerminkan itikad membayar","tidak dapat dinilai","baik tanpa perlu verifikasi lain","tergantung suku bunga"], kunci:3, pembahasan:"Kunci benar karena riwayat pembayaran lancar adalah bukti empiris kemauan membayar. Bukan berarti buruk atau tidak dapat dinilai, namun verifikasi lain tetap diperlukan dan Character tidak ditentukan suku bunga."},
{id:"SK-005", modul:"studi-kasus", kategori:"Kasus UMKM", level:2, soal:"Usaha rental mobil beromzet Rp90 juta per bulan dengan laba Rp18 juta per bulan. Cicilan kredit berjalan Rp10 juta per bulan, ditambah usulan kredit baru Rp8 juta per bulan. Keputusan yang tepat adalah", opsi:["disetujui karena laba masih positif","disetujui karena omzet besar","ditolak atau plafon diturunkan karena total cicilan Rp18 juta sama dengan laba sehingga DSCR = 1,0 tanpa margin pengaman","cicilan lama diabaikan","laba tidak relevan"], kunci:4, pembahasan:"Kunci benar karena total kewajiban 10 + 8 = Rp18 juta sama persis dengan laba Rp18 juta, sehingga DSCR = 1,0 tanpa ruang untuk guncangan. Laba positif dan omzet besar tidak cukup bila seluruhnya tersedot cicilan, dan cicilan berjalan wajib diperhitungkan."},
{id:"SK-006", modul:"studi-kasus", kategori:"Kasus UMKM", level:2, soal:"Warung makan mengajukan kredit Rp80 juta, tetapi omzetnya turun tiga bulan berturut-turut. Sikap analis yang tepat adalah", opsi:["menunda keputusan dan menganalisis penyebab penurunan omzet terlebih dahulu","langsung menyetujui karena usaha kuliner selalu prospektif","menolak permanen tanpa telaah","menaikkan plafon agar omzet naik","meminta agunan saja tanpa analisis usaha"], kunci:0, pembahasan:"Kunci benar karena tren menurun adalah sinyal peringatan yang harus ditelusuri sebelum memutus kredit. Persetujuan langsung, penolakan tanpa telaah, menaikkan plafon, atau hanya mengandalkan agunan bukan analisis yang baik."},
{id:"SK-007", modul:"studi-kasus", kategori:"Kasus UMKM", level:3, soal:"Peternak ayam petelur hanya panen raya dua kali setahun sehingga kas menumpuk di bulan tertentu dan kosong di bulan lain. Struktur kredit yang tepat adalah", opsi:["angsuran bulanan tetap","angsuran disesuaikan pola kas, misalnya ringan di luar panen dan besar saat panen","pelunasan di muka","bunga flat tinggi","tanpa jadwal"], kunci:1, pembahasan:"Kunci benar karena struktur pembayaran harus mengikuti pola arus kas musiman agar debitur tidak gagal bayar di luar musim. Angsuran bulanan tetap memaksa pembayaran saat kas kosong, sedangkan pelunasan di muka dan bunga tinggi tidak menyelesaikan ketidakselarasan pola kas."},
{id:"SK-008", modul:"studi-kasus", kategori:"Kasus UMKM", level:3, soal:"Eksportir mebel beromzet valas mengajukan kredit modal kerja rupiah. Risiko utama dan mitigasinya adalah", opsi:["risiko kurs; mitigasi dengan memantau eksposur valas dan mempertimbangkan lindung nilai","tidak ada risiko","risiko kurs tidak perlu dimitigasi","menolak karena ekspor","menaikkan bunga sebagai mitigasi kurs"], kunci:2, pembahasan:"Kunci benar karena pelemahan rupiah memengaruhi kewajiban dan daya saing eksportir; eksposur harus dipantau dan dapat dilindung nilai. Mengabaikan risiko, menolak karena ekspor, atau menaikkan bunga bukan mitigasi risiko kurs."},
{id:"SK-009", modul:"studi-kasus", kategori:"Plafon Wajar", level:1, soal:"Toko bangunan memiliki persediaan Rp80 juta, piutang dagang Rp60 juta, dan utang dagang Rp40 juta. Kebutuhan modal kerja satu siklus dan plafon wajarnya adalah", opsi:["Rp180 juta","Rp100 juta, dihitung dari 80 + 60 - 40","Rp40 juta","Rp20 juta","Rp200 juta"], kunci:3, pembahasan:"Kunci benar karena kebutuhan modal kerja = persediaan + piutang - utang dagang = Rp100 juta, sehingga plafon wajar sekitar angka tersebut. Menjumlahkan semuanya, hanya memakai utang dagang, atau angka lain tidak mencerminkan kebutuhan riil satu siklus."},
{id:"SK-010", modul:"studi-kasus", kategori:"Plafon Wajar", level:1, soal:"Pengusaha membeli mesin Rp200 juta dengan uang muka 30 persen dari dana sendiri. Plafon kredit investasi yang wajar adalah", opsi:["Rp200 juta penuh","Rp60 juta","Rp260 juta","Rp140 juta, yaitu 70 persen dari harga mesin","Rp100 juta"], kunci:4, pembahasan:"Kunci benar karena bank lazimnya membiayai maksimal 70-80 persen dari nilai investasi; 200 juta x 70 persen = Rp140 juta. Membiayai penuh mengabaikan partisipasi pemilik, sedangkan angka lain tidak sesuai proporsi."},
{id:"SK-011", modul:"studi-kasus", kategori:"Plafon Wajar", level:2, soal:"Distributor beromzet Rp1,2 miliar per tahun membutuhkan modal kerja untuk 3 bulan perputaran. Plafon KMK yang wajar adalah", opsi:["Rp300 juta, dihitung dari 1,2 miliar / 12 x 3","Rp1,2 miliar","Rp100 juta","Rp400 juta","Rp1,5 miliar"], kunci:0, pembahasan:"Kunci benar karena kebutuhan 3 bulan = omzet setahun dibagi 12 dikali 3 = Rp300 juta. Plafon sebesar omzet setahun atau angka lain melebihi kebutuhan riil dan menambah risiko."},
{id:"SK-012", modul:"studi-kasus", kategori:"Plafon Wajar", level:2, soal:"Laba bersih usaha Rp240 juta per tahun. Dengan DSCR minimal 1,2, cicilan tahunan maksimal yang dapat didukung adalah", opsi:["Rp240 juta","Rp288 juta","Rp200 juta, dihitung dari 240 / 1,2","Rp120 juta","Rp480 juta"], kunci:1, pembahasan:"Kunci benar karena cicilan maksimal = laba / DSCR minimal = 240 / 1,2 = Rp200 juta per tahun. Memakai seluruh laba tanpa margin, menambah 20 persen, atau menggandakan tidak memenuhi syarat pengaman."},
{id:"SK-013", modul:"studi-kasus", kategori:"Plafon Wajar", level:3, soal:"Proyek pembangunan ruko senilai Rp500 juta didanai pemilik Rp200 juta. Porsi pembiayaan bank yang wajar adalah", opsi:["Rp500 juta penuh","Rp200 juta","Rp300 juta, yaitu selisih kebutuhan dengan dana sendiri","Rp100 juta","Rp700 juta"], kunci:2, pembahasan:"Kunci benar karena bank membiayai kekurangan setelah partisipasi pemilik: 500 - 200 = Rp300 juta (60 persen). Membiayai penuh mengabaikan skin in the game pemilik yang penting sebagai mitigasi risiko."},
{id:"SK-014", modul:"studi-kasus", kategori:"Plafon Wajar", level:3, soal:"Debitur meminta plafon Rp1 miliar, tetapi proyeksi arus kas konservatif hanya mendukung cicilan untuk plafon Rp600 juta. Keputusan yang tepat adalah", opsi:["menyetujui Rp1 miliar sesuai permintaan","menolak seluruhnya","menyetujui Rp600 juta sesuai kemampuan bayar yang teruji","menyetujui Rp1 miliar dengan bunga lebih tinggi","meminta agunan Rp1 miliar lalu menyetujui penuh"], kunci:3, pembahasan:"Kunci benar karena plafon harus mengikuti kemampuan bayar, bukan permintaan. Menyetujui penuh mengabaikan analisis, menolak total membuang peluang yang layak, menaikkan bunga tidak menambah kas, dan agunan bukan sumber pelunasan."},
{id:"SK-015", modul:"studi-kasus", kategori:"Mitigasi", level:1, soal:"Nilai agunan hanya 90 persen dari plafon yang diajukan, sedangkan kebijakan bank mensyaratkan coverage minimal 120 persen. Mitigasi yang tepat adalah", opsi:["mengabaikan kebijakan","menurunkan nilai agunan","meminta tambahan agunan atau menurunkan plafon hingga coverage memenuhi syarat","menaikkan suku bunga","mempercepat pencairan"], kunci:4, pembahasan:"Kunci benar karena kekurangan coverage diatasi dengan menambah agunan atau menyesuaikan plafon. Mengabaikan kebijakan, memanipulasi nilai, menaikkan bunga, atau mempercepat pencairan tidak memperbaiki kecukupan pengaman."},
{id:"SK-016", modul:"studi-kasus", kategori:"Mitigasi", level:1, soal:"Agunan berupa gudang penyimpanan barang mudah terbakar. Mitigasi yang wajib disyaratkan bank adalah", opsi:["asuransi kebakaran atas objek agunan dengan bank sebagai penerima ganti rugi","tanpa perlindungan tambahan","menaikkan plafon","menurunkan suku bunga","mempercepat tenor"], kunci:0, pembahasan:"Kunci benar karena asuransi mengalihkan risiko fisik atas agunan kepada penanggung dengan bank sebagai pihak yang diuntungkan. Tanpa perlindungan, menaikkan plafon, menurunkan bunga, atau mempercepat tenor tidak melindungi nilai agunan."},
{id:"SK-017", modul:"studi-kasus", kategori:"Mitigasi", level:2, soal:"Mutasi usaha calon debitur tidak melalui rekening bank sehingga analis sulit memverifikasi omzet. Syarat mitigasi yang tepat adalah", opsi:["percaya pada omzet lisan","mewajibkan rekening penampungan di bank untuk seluruh transaksi usaha selama periode pemantauan","menolak tanpa solusi","menaikkan bunga","meminta laporan buatan"], kunci:1, pembahasan:"Kunci benar karena rekening penampungan memberi jejak transaksi yang dapat diverifikasi. Percaya omzet lisan, menolak tanpa solusi, menaikkan bunga, atau memakai laporan buatan bukan mitigasi yang sehat."},
{id:"SK-018", modul:"studi-kasus", kategori:"Mitigasi", level:2, soal:"Debitur baru tanpa riwayat kredit disetujui dengan plafon moderat. Mitigasi pasca-pencairan yang tepat adalah", opsi:["tanpa monitoring","monitoring berkala yang intensif disertai covenant pelaporan keuangan","langsung menaikkan plafon","menutup rekening","menghapus agunan"], kunci:2, pembahasan:"Kunci benar karena debitur baru berisiko informasi asimetris sehingga perlu pengawasan dan kewajiban lapor. Tanpa monitoring, menaikkan plafon dini, menutup rekening, atau menghapus agunan justru memperbesar risiko."},
{id:"SK-019", modul:"studi-kasus", kategori:"Mitigasi", level:3, soal:"Agunan berupa persediaan yang harganya fluktuatif di pasar. Paket mitigasi yang tepat adalah", opsi:["terima apa adanya","haircut atas nilai taksasi, inspeksi stok berkala, dan menjaga coverage ratio","tidak perlu dinilai","gunakan harga tertinggi","bebaskan dari pengikatan"], kunci:3, pembahasan:"Kunci benar karena haircut mengantisipasi penurunan harga, inspeksi memastikan barang benar ada, dan coverage ratio menjaga kecukupan. Menerima apa adanya, memakai harga tertinggi, atau membebaskan pengikatan mengabaikan risiko fluktuasi."},
{id:"SK-020", modul:"studi-kasus", kategori:"Mitigasi", level:3, soal:"Kelangsungan usaha sangat bergantung pada satu orang pemilik sebagai key person. Mitigasi yang tepat adalah", opsi:["mengabaikan","asuransi jiwa kredit atas key person dengan bank sebagai penerima manfaat","meminta pemilik berhenti bekerja","menaikkan bunga","memperpendek tenor menjadi satu bulan"], kunci:4, pembahasan:"Kunci benar karena asuransi jiwa kredit melindungi bank dari risiko kematian atau cacat key person. Mengabaikan, meminta berhenti bekerja, menaikkan bunga, atau tenor satu bulan bukan mitigasi yang relevan."},
{id:"SK-021", modul:"studi-kasus", kategori:"Kemampuan Bayar Lemah", level:1, soal:"Laba bersih Rp8 juta per bulan dan cicilan yang diajukan Rp10 juta per bulan. Keputusan yang tepat adalah", opsi:["ditolak karena DSCR = 8 / 10 = 0,8 kali, arus kas tidak cukup menutupi cicilan","disetujui karena selisih kecil","disetujui dengan harapan laba naik","cicilan ditambah","laba tidak penting"], kunci:0, pembahasan:"Kunci benar karena DSCR 0,8 berarti setiap Rp10 kewajiban hanya didukung Rp8 kas. Selisih kecil tetap berarti gagal bayar, harapan kenaikan laba bukan dasar persetujuan, dan laba sangat penting sebagai sumber pelunasan."},
{id:"SK-022", modul:"studi-kasus", kategori:"Kemampuan Bayar Lemah", level:1, soal:"Laba usaha turun 50 persen selama dua tahun berturut-turut dan debitur mengajukan kredit baru. Sikap analis yang tepat adalah", opsi:["menyetujui karena usaha lama","menilai kemampuan bayar melemah sehingga kredit baru sebaiknya ditolak atau direstrukturisasi setelah ditelusuri penyebabnya","menaikkan plafon agar laba pulih","mengabaikan tren","meminta debitur berjanji"], kunci:1, pembahasan:"Kunci benar karena tren laba turun tajam menandakan kemampuan bayar melemah dan harus ditelusuri. Usaha lama bukan jaminan, menaikkan plafon memperparah, mengabaikan tren bukan analisis, dan janji bukan mitigasi."},
{id:"SK-023", modul:"studi-kasus", kategori:"Kemampuan Bayar Lemah", level:2, soal:"Arus kas operasi perusahaan negatif Rp50 juta per bulan, tetapi mengajukan KMK Rp200 juta. Keputusan yang tepat adalah", opsi:["disetujui karena KMK untuk operasional","ditolak karena sumber pelunasan KMK seharusnya dari operasi yang justru negatif","plafon dinaikkan","bunga diturunkan","tenor diperpanjang"], kunci:2, pembahasan:"Kunci benar karena KMK dilunasi dari perputaran operasi; operasi yang negatif berarti tidak ada sumber pelunasan. Menyetujui, menaikkan plafon, menurunkan bunga, atau memperpanjang tenor tidak menciptakan kas operasi."},
{id:"SK-024", modul:"studi-kasus", kategori:"Kemampuan Bayar Lemah", level:2, soal:"Cicilan kredit berjalan sudah menyedot 70 persen laba bersih. Debitur mengajukan tambahan kredit. Keputusan yang tepat adalah", opsi:["disetujui karena masih ada sisa 30 persen","ditolak atau ditunda karena ruang kas tinggal 30 persen tanpa margin pengaman yang sehat","sisa laba tidak penting","cicilan lama diabaikan","bunga baru dibuat nol"], kunci:3, pembahasan:"Kunci benar karena 70 persen laba untuk cicilan menyisakan margin terlalu tipis terhadap guncangan usaha. Sisa 30 persen bukan ruang yang aman, cicilan lama wajib dihitung, dan bunga nol tidak menambah kas."},
{id:"SK-025", modul:"studi-kasus", kategori:"Kemampuan Bayar Lemah", level:3, soal:"Proyeksi laba debitur tumbuh 100 persen per tahun, padahal historisnya hanya tumbuh 5 persen tanpa perubahan fundamental usaha. Sikap analis yang tepat adalah", opsi:["memakai proyeksi apa adanya","menolak langsung","menguji dengan skenario konservatif berbasis historis dan meminta justifikasi atas asumsi pertumbuhan","meminta agunan lebih","menaikkan bunga"], kunci:4, pembahasan:"Kunci benar karena proyeksi yang tidak didukung fundamental harus diuji ulang dengan skenario hati-hati. Memakai apa adanya mengabaikan skeptisisme profesional, menolak langsung tanpa uji bukan analisis, sedangkan agunan dan bunga bukan koreksi atas proyeksi."},
{id:"SK-026", modul:"studi-kasus", kategori:"Kemampuan Bayar Lemah", level:3, soal:"DSCR tahunan 1,3 kali, tetapi empat bulan dalam setahun arus kasnya negatif karena usaha musiman. Struktur yang tepat adalah", opsi:["menyesuaikan jadwal angsuran dengan pola musim, misalnya grace period di bulan sepi","angsuran bulanan tetap karena tahunan cukup","menolak karena ada bulan negatif","menaikkan plafon","mempercepat pelunasan"], kunci:0, pembahasan:"Kunci benar karena DSCR tahunan menyembunyikan defisit bulanan; jadwal harus mengikuti pola kas. Angsuran tetap memaksa bayar saat kas kosong, menolak mengabaikan kelayakan tahunan, dan menaikkan plafon tidak menyelesaikan ketidakselarasan waktu."},
{id:"SK-027", modul:"studi-kasus", kategori:"Laporan Keuangan Bermasalah", level:1, soal:"Piutang dagang naik 200 persen sementara penjualan hanya naik 20 persen. Indikasi yang harus diwaspadai analis adalah", opsi:["penagihan sangat baik","piutang tak tertagih atau penjualan fiktif","persediaan laku keras","kas melimpah","utang lunas"], kunci:1, pembahasan:"Kunci benar karena piutang yang tumbuh jauh di atas penjualan menandakan penagihan macet atau penjualan yang tidak didukung kas. Ini kebalikan dari penagihan baik, tidak berkaitan dengan persediaan laku, kas melimpah, atau utang lunas."},
{id:"SK-028", modul:"studi-kasus", kategori:"Laporan Keuangan Bermasalah", level:1, soal:"Persediaan menumpuk dua kali lipat dalam setahun padahal penjualan stagnan. Risiko bagi bank adalah", opsi:["likuiditas membaik","barang berisiko usang dan kas tertahan sehingga kemampuan bayar menurun","laba pasti naik","utang turun","tidak ada risiko"], kunci:2, pembahasan:"Kunci benar karena persediaan menumpuk mengunci kas dan berisiko usang atau turun nilai. Ini menurunkan likuiditas, bukan menaikkan laba atau menurunkan utang, dan jelas merupakan risiko."},
{id:"SK-029", modul:"studi-kasus", kategori:"Laporan Keuangan Bermasalah", level:2, soal:"Days sales outstanding (DSO) naik dari 30 hari menjadi 90 hari. Artinya", opsi:["penagihan semakin cepat","rata-rata piutang tertagih dalam 90 hari sehingga perputaran kas melambat dan risiko piutang macet naik","penjualan tunai meningkat","kas bertambah","tidak ada masalah"], kunci:3, pembahasan:"Kunci benar karena DSO = piutang / penjualan x 365; kenaikan ke 90 hari berarti kas tertahan tiga kali lebih lama. Ini kebalikan dari penagihan cepat, bukan penjualan tunai, tidak menambah kas, dan merupakan masalah."},
{id:"SK-030", modul:"studi-kasus", kategori:"Laporan Keuangan Bermasalah", level:2, soal:"Aset lancar Rp500 juta dan utang lancar Rp700 juta. Kondisi dan implikasinya adalah", opsi:["modal kerja positif","modal kerja negatif Rp200 juta sehingga likuiditas kritis","tidak punya utang","sangat likuid","laba besar"], kunci:4, pembahasan:"Kunci benar karena modal kerja = 500 - 700 = negatif Rp200 juta dengan CR 0,71 kali. Ini kebalikan dari positif, likuid, atau laba besar, dan perusahaan jelas memiliki utang lancar."},
{id:"SK-031", modul:"studi-kasus", kategori:"Laporan Keuangan Bermasalah", level:2, soal:"Laba bersih naik, tetapi arus kas operasi turun tiga tahun berturut-turut. Kesimpulan analis adalah", opsi:["kualitas laba buruk karena laba tidak didukung kas sehingga kemampuan bayar meragukan","kualitas laba baik","perusahaan sehat","kas tidak penting","kredit layak"], kunci:0, pembahasan:"Kunci benar karena divergensi laba dan kas menandakan laba akrual yang tidak menjadi kas. Ini bukan kualitas baik atau tanda sehat, kas sangat penting bagi analis kredit, dan kelayakan belum dapat disimpulkan."},
{id:"SK-032", modul:"studi-kasus", kategori:"Laporan Keuangan Bermasalah", level:3, soal:"Utang dagang naik tajam 150 persen dalam setahun sementara kas menipis. Indikasi yang tepat adalah", opsi:["supplier memberi kepercayaan lebih","perusahaan kesulitan membayar pemasok sehingga menunda pembayaran, sinyal tekanan likuiditas","laba meningkat","tidak ada masalah","modal bertambah"], kunci:1, pembahasan:"Kunci benar karena lonjakan utang dagang bersamaan kas menipis menandakan perusahaan menahan pembayaran karena kekurangan kas. Ini bukan kepercayaan supplier, bukan laba naik, dan merupakan masalah likuiditas."},
{id:"SK-033", modul:"studi-kasus", kategori:"Laporan Keuangan Bermasalah", level:3, soal:"Total ekuitas perusahaan negatif Rp100 juta karena akumulasi rugi. Implikasi bagi analis kredit adalah", opsi:["permodalan kuat","perusahaan insolven secara teknis karena liabilitas melebihi aset sehingga risiko kredit sangat tinggi","tidak berpengaruh","layak diberi plafon besar","rugi tidak penting"], kunci:2, pembahasan:"Kunci benar karena ekuitas negatif berarti aset tidak cukup menutupi utang bila dilikuidasi. Ini kebalikan dari permodalan kuat, sangat berpengaruh, tidak layak plafon besar, dan rugi sangat penting."},
{id:"SK-034", modul:"studi-kasus", kategori:"Laporan Keuangan Bermasalah", level:3, soal:"Perputaran persediaan melambat dari 6 kali menjadi 2 kali per tahun. Artinya", opsi:["persediaan semakin cepat terjual","persediaan menumpuk dan kas tertahan lebih lama sehingga efisiensi menurun","penjualan meningkat","tidak ada dampak","laba naik"], kunci:3, pembahasan:"Kunci benar karena perputaran 2 kali berarti rata-rata persediaan mengendap 180 hari, jauh lebih lama dari sebelumnya 60 hari. Ini kebalikan dari cepat terjual dan penjualan meningkat, jelas berdampak, dan menekan laba."},
{id:"SK-035", modul:"studi-kasus", kategori:"Indikasi Fraud", level:1, soal:"Ditemukan dua faktur dengan nomor sama yang dipakai untuk pengajuan plafon. Tindakan analis yang tepat adalah", opsi:["mengabaikan","memakai yang nilainya besar","menolak pengajuan dan mencatat indikasi pemalsuan dokumen","meminta dibuatkan yang ketiga","menaikkan plafon"], kunci:4, pembahasan:"Kunci benar karena faktur ganda adalah indikasi fraud yang merusak kepercayaan atas seluruh dokumen. Mengabaikan, memilih nilai besar, meminta dokumen ketiga, atau menaikkan plafon bukan respons atas indikasi pemalsuan."},
{id:"SK-036", modul:"studi-kasus", kategori:"Indikasi Fraud", level:1, soal:"Nama pada KTP berbeda dengan nama pada dokumen kepemilikan agunan. Langkah analis yang tepat adalah", opsi:["memverifikasi keaslian identitas dan kepemilikan karena berpotensi dokumen palsu atau agunan bukan milik debitur","mengabaikan perbedaan","melanjutkan pencairan","meminta fotokopi saja","mengganti nama sendiri"], kunci:0, pembahasan:"Kunci benar karena ketidaksesuaian identitas adalah red flag yang harus diverifikasi sebelum melangkah. Mengabaikan, melanjutkan pencairan, atau hanya meminta fotokopi membiarkan risiko hukum atas agunan."},
{id:"SK-037", modul:"studi-kasus", kategori:"Indikasi Fraud", level:2, soal:"Rekening koran menunjukkan pola setor-tarik berulang dalam jumlah besar di hari yang sama. Indikasi yang tepat adalah", opsi:["omzet riil yang sehat","penggelembungan omzet melalui transaksi semu","tabungan meningkat","tidak ada indikasi","keuntungan besar"], kunci:1, pembahasan:"Kunci benar karena pola setor-tarik berulang lazim dipakai untuk menggelembungkan mutasi seolah omzet besar. Ini bukan omzet riil, bukan tabungan meningkat, dan merupakan indikasi yang harus ditelusuri."},
{id:"SK-038", modul:"studi-kasus", kategori:"Indikasi Fraud", level:2, soal:"Pengecekan ke BPN menunjukkan sertifikat agunan sudah dibebani hak tanggungan bank lain. Sikap analis yang tepat adalah", opsi:["tetap menerima tanpa verifikasi","menolak atau meminta pelunasan dan roya terlebih dahulu karena agunan sudah terikat pihak lain","menaikkan plafon","mengabaikan hasil cek","meminta fotokopi sertifikat"], kunci:2, pembahasan:"Kunci benar karena agunan yang sudah dibebani tidak dapat memberi kedudukan preferen kepada bank baru tanpa penyelesaian. Menerima tanpa verifikasi, menaikkan plafon, mengabaikan, atau hanya meminta fotokopi membiarkan bank tanpa pengaman."},
{id:"SK-039", modul:"studi-kasus", kategori:"Indikasi Fraud", level:2, soal:"Laporan keuangan yang diserahkan ke bank jauh lebih bagus daripada yang dilaporkan ke otoritas pajak. Kesimpulan analis adalah", opsi:["wajar karena beda keperluan","dokumen tidak dapat dipercaya sehingga pengajuan sebaiknya ditolak","memakai versi bank","memakai versi pajak","meminta versi ketiga"], kunci:3, pembahasan:"Kunci benar karena dua versi laporan menandakan manipulasi sehingga seluruh informasi keuangan meragukan. Beda keperluan bukan pembenaran, memilih salah satu versi tetap memakai data yang diragukan, dan versi ketiga tidak menyelesaikan masalah kepercayaan."},
{id:"SK-040", modul:"studi-kasus", kategori:"Indikasi Fraud", level:3, soal:"Ditemukan transaksi besar dengan perusahaan afiliasi tanpa dasar bisnis yang jelas menjelang pengajuan kredit. Indikasi dan tindak lanjutnya adalah", opsi:["transaksi normal","waspada pengalihan dana atau rekayasa laporan sehingga perlu ditelusuri substansi transaksinya","abaikan karena afiliasi","tambah plafon","minta direksi afiliasi menjamin"], kunci:4, pembahasan:"Kunci benar karena transaksi afiliasi tanpa substansi lazim dipakai untuk menggelembungkan kinerja atau mengalihkan dana. Menganggap normal, mengabaikan, menambah plafon, atau meminta jaminan afiliasi tanpa telaah bukan respons yang tepat."},
{id:"SK-041", modul:"studi-kasus", kategori:"Indikasi Fraud", level:3, soal:"Saat kunjungan usaha, lokasi ternyata tutup dan tidak ada aktivitas, padahal laporan keuangan menunjukkan usaha ramai. Kesimpulan yang tepat adalah", opsi:["usaha fiktif sehingga pengajuan harus ditolak","tetap disetujui berdasarkan laporan","kunjungan tidak penting","minta laporan baru","tutupnya sementara pasti"], kunci:0, pembahasan:"Kunci benar karena verifikasi fisik adalah uji kebenaran usaha; lokasi tutup membuktikan data tidak valid. Menyetujui berdasarkan laporan, menganggap kunjungan tidak penting, meminta laporan baru, atau berasumsi tutup sementara mengabaikan bukti fisik."},
{id:"SK-042", modul:"studi-kasus", kategori:"Indikasi Fraud", level:3, soal:"Invoice pemasok yang dilampirkan ternyata dari perusahaan yang tidak terdaftar dan tidak dapat dihubungi. Tindak lanjut analis adalah", opsi:["terima apa adanya","verifikasi silang ke pemasok dan waspadai invoice fiktif untuk menggelembungkan kebutuhan dana","minta invoice lebih banyak","naikkan plafon","abaikan"], kunci:1, pembahasan:"Kunci benar karena pemasok fiktif menandakan kebutuhan dana yang direkayasa. Menerima apa adanya, meminta lebih banyak invoice sejenis, menaikkan plafon, atau mengabaikan memperbesar risiko fraud."},
{id:"SK-043", modul:"studi-kasus", kategori:"Kasus SLIK & Agunan", level:1, soal:"Hasil SLIK calon debitur menunjukkan kolektibilitas 5 di dua bank. Keputusan yang tepat adalah", opsi:["disetujui","ditolak karena riwayat macet menunjukkan itikad dan kemampuan bayar yang buruk","diminta agunan kecil","bunga diturunkan","plafon dinaikkan"], kunci:2, pembahasan:"Kunci benar karena kolektibilitas 5 (Macet) di dua bank adalah bukti kuat kegagalan membayar. Menyetujui, meminta agunan kecil, menurunkan bunga, atau menaikkan plafon mengabaikan rekam jejak tersebut."},
{id:"SK-044", modul:"studi-kasus", kategori:"Kasus SLIK & Agunan", level:2, soal:"SHM yang diagunkan atas nama orang tua debitur. Agar dapat dipakai sebagai agunan, yang diperlukan adalah", opsi:["tanpa persetujuan pemilik","persetujuan tertulis pemilik dan pengikatan hak tanggungan yang melibatkan pemilik sebagai pemberi jaminan","cukup fotokopi KTP pemilik","ganti nama debitur sendiri","abaikan status nama"], kunci:3, pembahasan:"Kunci benar karena jaminan atas milik pihak ketiga sah bila pemilik menyetujui dan ikut dalam pengikatan. Tanpa persetujuan, hanya fotokopi, mengganti nama, atau mengabaikan membuat pengikatan cacat hukum."},
{id:"SK-045", modul:"studi-kasus", kategori:"Kasus SLIK & Agunan", level:3, soal:"Calon debitur tercatat kolektibilitas 2 (DPK) karena pernah telat 60 hari, tetapi usaha prospektif dan DSCR 1,8 kali. Keputusan yang tepat adalah", opsi:["tolak otomatis","abaikan catatan","dapat dipertimbangkan dengan mitigasi ketat karena keterlambatan ringan yang sudah pulih tidak menghapus kelayakan usaha yang prospektif","minta lunas dulu semua","naikkan bunga sebagai hukuman"], kunci:4, pembahasan:"Kunci benar karena kol 2 dari keterlambatan 60 hari yang telah pulih adalah catatan ringan; dengan prospek baik dan DSCR kuat, kredit dapat dipertimbangkan dengan mitigasi. Penolakan otomatis berlebihan, mengabaikan bukan analisis, pelunasan total tidak relevan, dan hukuman bunga bukan mitigasi."},
];
